window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["drill-hazard-warn"]={"pkg":{"id":"drill-hazard-warn","sceneId":"d2","methods":["ts"],"title":"多通道随钻时序井下复杂事故前兆预警","version":"1.0.0","updated":"2026-11-01","tabs":{"background":{"label":"专业背景","lede":"在深井与超深井钻井作业中，**卡钻（Pipe Sticking）**、**井漏（Lost Circulation）**与**气侵溢流（Gas Kick）**是威胁井筒安全与钻井周期的三大恶性复杂事故。尽管综合录井仪以 1–10 秒间隔持续采集立管压力、转盘扭矩、大钩载荷、进出口流量差与泥浆池体积等多通道随钻时序参数，但传统现场报警器依赖**单通道固定阈值**，在接单根、开停泵等常规作业瞬态下频繁误报，导致司钻因「狼来了」效应关闭报警，从而错失事故爆发前 **15–25 分钟的黄金处置时间窗**。","judge":[{"label":"数据形态","value":"多通道随钻工程录井时序","desc":"WITSML 实时流（0.2–1 Hz）：大钩载荷、扭矩、立压、流量差 ΔQ、池体积 ΔV、钻速 ROP"},{"label":"核心痛点","value":"接单根瞬态误报与微弱前兆漏报","desc":"单通道阈值无法区分「接单根开停泵瞬态冲击」与「环空岩屑床/气侵渐进耦合漂移」"},{"label":"AI 切入点","value":"工况状态机 + 多变量重构 + CUSUM","desc":"自动屏蔽接单根瞬态，计算多通道马氏重构残差并经 CUSUM 序贯累积捕获早期前兆"},{"label":"核心收益","value":"提前 14–20 min 零误报分级预警","desc":"不仅给出黄/红分级报警，还实时拆解各通道异常贡献度并匹配三类事故物理签名"}],"sections":[{"no":1,"en":"","title":"当前做法与问题","html":"<p>在旋转钻进过程中，钻井液由地面泥浆泵经立管打入钻柱内腔，从井底钻头水眼喷出冷却钻头并携带岩屑，再沿井壁与钻柱之间的<strong>环空（Annulus）</strong>上返至地面泥浆池，构成密闭循环回路。井下任何力学失稳或地层流体侵入都会改变这一水力—机械耦合系统的平衡：</p>\n<ul>\n  <li><strong>渐进性卡钻（Pipe Sticking）</strong>：当环空携岩不良形成岩屑床（Pack-off）或泥页岩吸水缩径时，钻具旋转阻力增大且上返流道受阻，表现为<strong>转盘扭矩持续爬升并伴随锯齿状卡滞尖峰、立管压力（SPP）同步抬升、上提摩阻异常增大且返出流量微降</strong>。</li>\n  <li><strong>裂缝性井漏（Lost Circulation）</strong>：当井底激动压力超过地层漏失压力时，钻井液大量涌入天然或诱导裂缝，表现为<strong>返出流量差 ΔQ = Q_out − Q_in 骤降为负值、泥浆池总体积持续亏空、立管压力缓慢回落</strong>。</li>\n  <li><strong>气侵溢流（Gas Kick）</strong>：钻穿高压油气层初期常出现机械钻速突增（Drilling Break），随后地层高压气侵入环空并在上返减压过程中膨胀顶出泥浆，表现为<strong>返出流量差 ΔQ 显著大于零、泥浆池液位异常上涨、立压因环空泥浆气侵密度下降而缓降</strong>。</li>\n</ul>\n<div class=\"figure\"><svg viewBox=\"0 0 760 310\" width=\"100%\" role=\"img\" aria-label=\"钻井液循环系统与三类井下复杂事故多参数耦合签名对照图\">\n  <defs>\n    <linearGradient id=\"dhw-f1-earth\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#e4d6b8\" stop-opacity=\"0.45\"/>\n      <stop offset=\"55%\" stop-color=\"#d9c7a3\" stop-opacity=\"0.55\"/>\n      <stop offset=\"100%\" stop-color=\"#c9b28a\" stop-opacity=\"0.65\"/>\n    </linearGradient>\n    <marker id=\"dhw-arr-teal\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#12615a\"/>\n    </marker>\n    <marker id=\"dhw-arr-red\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#b4483c\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"310\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left Panel: Wellbore Circulation & 6 Telemetry Sensors -->\n  <rect x=\"12\" y=\"12\" width=\"318\" height=\"286\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"24\" y=\"31\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">A. 钻井液循环回路与六通道随钻传感器布局</text>\n  <!-- Formation background -->\n  <rect x=\"24\" y=\"102\" width=\"210\" height=\"184\" rx=\"4\" fill=\"url(#dhw-f1-earth)\" stroke=\"#d9d4c8\"/>\n  <line x1=\"24\" y1=\"158\" x2=\"234\" y2=\"158\" stroke=\"#b9a27c\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"24\" y1=\"216\" x2=\"234\" y2=\"216\" stroke=\"#b9a27c\" stroke-dasharray=\"4,3\"/>\n  <text x=\"30\" y=\"120\" fill=\"#737c83\" font-size=\"10\">上部砂泥岩层</text>\n  <text x=\"30\" y=\"176\" fill=\"#737c83\" font-size=\"10\">易坍塌/裂缝发育带</text>\n  <text x=\"30\" y=\"234\" fill=\"#737c83\" font-size=\"10\">深部高压含气储层</text>\n  <!-- Derrick & Traveling Block -->\n  <path d=\"M104,98 L116,42 L142,42 L154,98\" fill=\"none\" stroke=\"#424a50\" stroke-width=\"2\"/>\n  <line x1=\"110\" y1=\"68\" x2=\"148\" y2=\"68\" stroke=\"#737c83\" stroke-width=\"1.2\"/>\n  <rect x=\"121\" y=\"50\" width=\"16\" height=\"14\" rx=\"2\" fill=\"#3a6ea5\"/>\n  <!-- Wellbore & Casing -->\n  <rect x=\"96\" y=\"102\" width=\"66\" height=\"172\" fill=\"#e3efec\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n  <path d=\"M96,102 L96,148 L88,154 M162,102 L162,148 L170,154\" fill=\"none\" stroke=\"#15191c\" stroke-width=\"2.5\"/>\n  <!-- Drillstring & Bit -->\n  <rect x=\"122\" y=\"64\" width=\"14\" height=\"194\" fill=\"#424a50\"/>\n  <rect x=\"113\" y=\"258\" width=\"32\" height=\"14\" rx=\"3\" fill=\"#15191c\"/>\n  <!-- Mud flow arrows: down drillpipe, up annulus -->\n  <line x1=\"129\" y1=\"90\" x2=\"129\" y2=\"245\" stroke=\"#ffffff\" stroke-width=\"1.4\" stroke-dasharray=\"4,3\"/>\n  <path d=\"M107,252 L107,118\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#dhw-arr-teal)\"/>\n  <path d=\"M151,252 L151,118\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.6\" marker-end=\"url(#dhw-arr-teal)\"/>\n  <!-- Mud Pump & Pit on right of wellbore -->\n  <rect x=\"246\" y=\"198\" width=\"72\" height=\"46\" rx=\"4\" fill=\"#e3ecf6\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <text x=\"282\" y=\"218\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10.5\" font-weight=\"600\">泥浆池 Pit</text>\n  <text x=\"282\" y=\"234\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\">液位传感器 ΔV</text>\n  <!-- Standpipe & Return line -->\n  <path d=\"M268,198 L268,78 L136,78\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2\" marker-end=\"url(#dhw-arr-teal)\"/>\n  <path d=\"M162,110 L252,110 L252,198\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"1.8\" stroke-dasharray=\"4,2\" marker-end=\"url(#dhw-arr-red)\"/>\n  <!-- Sensor Callout Badges -->\n  <rect x=\"18\" y=\"44\" width=\"84\" height=\"22\" rx=\"4\" fill=\"#e3ecf6\" stroke=\"#3a6ea5\"/>\n  <text x=\"60\" y=\"59\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"10\" font-weight=\"600\">①大钩载荷/钻速</text>\n  <rect x=\"18\" y=\"72\" width=\"84\" height=\"22\" rx=\"4\" fill=\"#f7ecdd\" stroke=\"#c27a2c\"/>\n  <text x=\"60\" y=\"87\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"10\" font-weight=\"600\">②转盘扭矩 Torq</text>\n  <rect x=\"186\" y=\"54\" width=\"82\" height=\"20\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"227\" y=\"68\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10\" font-weight=\"600\">③立管压力 SPP</text>\n  <rect x=\"186\" y=\"118\" width=\"132\" height=\"22\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\"/>\n  <text x=\"252\" y=\"133\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"600\">④返出流量差 ΔQ=Qout-Qin</text>\n  <!-- In-wellbore hazard markers -->\n  <ellipse cx=\"106\" cy=\"175\" rx=\"9\" ry=\"16\" fill=\"#c27a2c\" opacity=\"0.75\"/>\n  <ellipse cx=\"152\" cy=\"175\" rx=\"9\" ry=\"16\" fill=\"#c27a2c\" opacity=\"0.75\"/>\n  <text x=\"91\" y=\"198\" text-anchor=\"end\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">岩屑床(卡钻)</text>\n  <path d=\"M162,202 L192,194 M162,208 L194,215\" stroke=\"#3a6ea5\" stroke-width=\"2\"/>\n  <text x=\"198\" y=\"210\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"700\">裂缝漏失</text>\n  <circle cx=\"110\" cy=\"242\" r=\"4\" fill=\"#b4483c\"/><circle cx=\"148\" cy=\"232\" r=\"5\" fill=\"#b4483c\"/>\n  <text x=\"91\" y=\"256\" text-anchor=\"end\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">高压气侵↑</text>\n\n  <!-- Right Panel: Multi-Parameter Coupling Matrix -->\n  <rect x=\"340\" y=\"12\" width=\"408\" height=\"286\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"354\" y=\"31\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">B. 三类井下复杂事故物理机制与多通道耦合签名矩阵</text>\n  <text x=\"354\" y=\"48\" fill=\"#737c83\" font-size=\"10.5\">单通道涨落方向存在歧义，唯有多通道协同耦合矢量才能唯一锁定事故机理：</text>\n\n  <!-- Card 1: Pipe Sticking -->\n  <rect x=\"352\" y=\"58\" width=\"384\" height=\"72\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#c27a2c\" stroke-width=\"1.3\"/>\n  <rect x=\"352\" y=\"58\" width=\"8\" height=\"72\" rx=\"3\" fill=\"#c27a2c\"/>\n  <text x=\"368\" y=\"76\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">1. 渐进性卡钻 (Pipe Sticking · 岩屑床堵塞 / 井壁缩径)</text>\n  <text x=\"368\" y=\"93\" fill=\"#424a50\" font-size=\"10.5\">机理：岩屑携出不良在环空堆积形成「砂桥」，憋堵钻井液上返通道并抱死钻具。</text>\n  <g font-family=\"ui-monospace,Consolas,monospace\" font-size=\"10.5\" font-weight=\"700\">\n    <rect x=\"368\" y=\"101\" width=\"86\" height=\"20\" rx=\"4\" fill=\"#f7ecdd\"/><text x=\"411\" y=\"115\" text-anchor=\"middle\" fill=\"#c27a2c\">扭矩 Torq ↑↑</text>\n    <rect x=\"460\" y=\"101\" width=\"86\" height=\"20\" rx=\"4\" fill=\"#f7ecdd\"/><text x=\"503\" y=\"115\" text-anchor=\"middle\" fill=\"#c27a2c\">立压 SPP ↑↑</text>\n    <rect x=\"552\" y=\"101\" width=\"90\" height=\"20\" rx=\"4\" fill=\"#e3ecf6\"/><text x=\"597\" y=\"115\" text-anchor=\"middle\" fill=\"#3a6ea5\">大钩摩阻 ↑</text>\n    <rect x=\"648\" y=\"101\" width=\"78\" height=\"20\" rx=\"4\" fill=\"#e2f0e8\"/><text x=\"687\" y=\"115\" text-anchor=\"middle\" fill=\"#2f7d5b\">返出 ΔQ ↘</text>\n  </g>\n\n  <!-- Card 2: Lost Circulation -->\n  <rect x=\"352\" y=\"138\" width=\"384\" height=\"72\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <rect x=\"352\" y=\"138\" width=\"8\" height=\"72\" rx=\"3\" fill=\"#3a6ea5\"/>\n  <text x=\"368\" y=\"156\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">2. 裂缝性井漏 (Lost Circulation · 井底动压超过地层漏失压力)</text>\n  <text x=\"368\" y=\"173\" fill=\"#424a50\" font-size=\"10.5\">机理：钻遇天然或诱导裂缝带，钻井液大量漏入地层，上返环空流体锐减。</text>\n  <g font-family=\"ui-monospace,Consolas,monospace\" font-size=\"10.5\" font-weight=\"700\">\n    <rect x=\"368\" y=\"181\" width=\"96\" height=\"20\" rx=\"4\" fill=\"#e3ecf6\"/><text x=\"416\" y=\"195\" text-anchor=\"middle\" fill=\"#3a6ea5\">流量差 ΔQ ↓↓</text>\n    <rect x=\"470\" y=\"181\" width=\"88\" height=\"20\" rx=\"4\" fill=\"#e3ecf6\"/><text x=\"514\" y=\"195\" text-anchor=\"middle\" fill=\"#3a6ea5\">池体积 ΔV ↓</text>\n    <rect x=\"564\" y=\"181\" width=\"82\" height=\"20\" rx=\"4\" fill=\"#e3efec\"/><text x=\"605\" y=\"195\" text-anchor=\"middle\" fill=\"#12615a\">立压 SPP ↓</text>\n    <rect x=\"652\" y=\"181\" width=\"74\" height=\"20\" rx=\"4\" fill=\"#f0ede5\"/><text x=\"689\" y=\"195\" text-anchor=\"middle\" fill=\"#737c83\">扭矩 平稳</text>\n  </g>\n\n  <!-- Card 3: Gas Kick -->\n  <rect x=\"352\" y=\"218\" width=\"384\" height=\"72\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#b4483c\" stroke-width=\"1.3\"/>\n  <rect x=\"352\" y=\"218\" width=\"8\" height=\"72\" rx=\"3\" fill=\"#b4483c\"/>\n  <text x=\"368\" y=\"236\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">3. 气侵溢流 (Gas Kick · 地层孔隙压力大于环空液柱压力)</text>\n  <text x=\"368\" y=\"253\" fill=\"#424a50\" font-size=\"10.5\">机理：钻穿高压气层初期钻速突增(Drilling Break)，随后高压气侵入环空膨胀顶出泥浆。</text>\n  <g font-family=\"ui-monospace,Consolas,monospace\" font-size=\"10.5\" font-weight=\"700\">\n    <rect x=\"368\" y=\"261\" width=\"90\" height=\"20\" rx=\"4\" fill=\"#ebe7f5\"/><text x=\"413\" y=\"275\" text-anchor=\"middle\" fill=\"#6b5aa6\">钻速 ROP ↑↑</text>\n    <rect x=\"464\" y=\"261\" width=\"94\" height=\"20\" rx=\"4\" fill=\"#f6e3df\"/><text x=\"511\" y=\"275\" text-anchor=\"middle\" fill=\"#b4483c\">流量差 ΔQ ↑↑</text>\n    <rect x=\"564\" y=\"261\" width=\"84\" height=\"20\" rx=\"4\" fill=\"#f6e3df\"/><text x=\"606\" y=\"275\" text-anchor=\"middle\" fill=\"#b4483c\">池增量 ΔV ↑</text>\n    <rect x=\"654\" y=\"261\" width=\"72\" height=\"20\" rx=\"4\" fill=\"#f7ecdd\"/><text x=\"690\" y=\"275\" text-anchor=\"middle\" fill=\"#c27a2c\">立压 缓降↓</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 1</b><span>钻井液循环传感拓扑与卡钻、井漏、气侵溢流三类井下复杂事故的多参数耦合方向对照矩阵。</span></div>\n<p>然而，司钻房现有的商业录井报警器普遍采用<strong>单通道独立上限/下限阈值</strong>，在工程现场面临严峻的「误报—迟钝」两难困境：钻井过程中每隔约 9–10 米（单根长度）就必须停钻进行<strong>接单根（Pipe Connection）</strong>作业，期间座卡瓦、卸扣、停泵、开泵和划眼会引起大钩载荷、扭矩与立压的剧烈瞬态阶跃，触发成百上千次假警报。司钻被迫将报警门限大幅调宽甚至静音，结果真正阴险的跨通道渐进式前兆漂移在潜伏期（事故前 15–25 分钟）被完全忽略，直到钻具彻底卡死或井口发生溢流才仓促应对。</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 245\" width=\"100%\" role=\"img\" aria-label=\"单通道固定阈值报警的狼来了误报困境与黄金处置时间窗\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"245\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"25\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">单通道固定阈值「狼来了」误报困境 vs 多变量协同前兆黄金处置窗 (15–25 min)</text>\n  <!-- Timeline plot box -->\n  <rect x=\"58\" y=\"38\" width=\"684\" height=\"168\" rx=\"4\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <!-- Connection transient zones -->\n  <rect x=\"172\" y=\"38\" width=\"38\" height=\"168\" fill=\"rgba(194,122,44,0.16)\"/>\n  <rect x=\"308\" y=\"38\" width=\"38\" height=\"168\" fill=\"rgba(194,122,44,0.16)\"/>\n  <text x=\"191\" y=\"52\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">接单根#1</text>\n  <text x=\"327\" y=\"52\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">接单根#2</text>\n  <!-- Golden window zone -->\n  <rect x=\"415\" y=\"38\" width=\"215\" height=\"168\" fill=\"rgba(18,97,90,0.08)\"/>\n  <line x1=\"415\" y1=\"38\" x2=\"415\" y2=\"206\" stroke=\"#12615a\" stroke-dasharray=\"4,3\"/>\n  <line x1=\"630\" y1=\"38\" x2=\"630\" y2=\"206\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n  <text x=\"522\" y=\"54\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10.5\" font-weight=\"700\">黄金处置时间窗 (提前 15–22 min 干预)</text>\n  <text x=\"630\" y=\"33\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"700\">事故爆发 (50 min)</text>\n\n  <!-- Fixed high threshold line -->\n  <line x1=\"58\" y1=\"92\" x2=\"742\" y2=\"92\" stroke=\"#b4483c\" stroke-width=\"1.3\" stroke-dasharray=\"6,3\"/>\n  <text x=\"66\" y=\"86\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"600\">传统单通道固定高阈值 (防误报调高后迟钝，仅提前 2 min 报警)</text>\n\n  <!-- Raw torque curve with giant spikes during pipe connections and subtle creep in precursor -->\n  <path d=\"M60,165 L168,163 L182,66 L195,185 L208,162 L302,160 L318,62 L332,182 L346,158 L415,154 L465,142 L515,126 L565,108 L612,91 L630,55 L725,52\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"2\"/>\n  <circle cx=\"182\" cy=\"66\" r=\"5\" fill=\"#c27a2c\"/><text x=\"182\" y=\"60\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">误报①(停泵卸扣)</text>\n  <circle cx=\"318\" cy=\"62\" r=\"5\" fill=\"#c27a2c\"/><text x=\"318\" y=\"56\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">误报②(划眼开泵)</text>\n\n  <!-- AI Multivariate CUSUM curve (smooth in connections, rises sharply in precursor) -->\n  <path d=\"M60,188 L175,186 L195,183 L315,186 L345,184 L415,178 L455,152 L492,112 L530,82 L630,48\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\"/>\n  <circle cx=\"482\" cy=\"122\" r=\"5\" fill=\"#12615a\" stroke=\"#fff\" stroke-width=\"1.5\"/>\n  <rect x=\"430\" y=\"128\" width=\"148\" height=\"20\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"504\" y=\"142\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\">AI 多变量预警 (t=34.5m)</text>\n\n  <!-- X axis labels -->\n  <g fill=\"#737c83\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" text-anchor=\"middle\">\n    <text x=\"60\" y=\"222\">0 min</text><text x=\"191\" y=\"222\">12 min</text><text x=\"327\" y=\"222\">24 min</text>\n    <text x=\"415\" y=\"222\">28 min(前兆)</text><text x=\"504\" y=\"222\">35 min(预警)</text><text x=\"630\" y=\"222\">50 min(卡钻)</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 2</b><span>接单根与开停泵瞬态冲击导致传统单通道阈值频繁误报（「狼来了」效应），而调高阈值又会错失 15–25 分钟的黄金处置窗。</span></div>"},{"no":2,"en":"","title":"AI 能做什么","html":"<p>针对随钻多通道时序强耦合、多工况切换、高噪声的特点，工业界落地的智能化方案并非黑箱式的端到端报警，而是构建<strong>「工况状态机切分 → 深度趋势去漂移 → 多变量时序自编码器重构残差 → CUSUM 序贯累积与通道归因」</strong>的四级可解释流水线：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"工况状态机过滤与多变量自编码器及CUSUM分级预警架构图\">\n  <defs>\n    <marker id=\"dhw-f3-ar\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\">\n      <path d=\"M0,1 L9,5 L0,9 Z\" fill=\"#424a50\"/>\n    </marker>\n  </defs>\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"250\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Box 1: 6-Ch WITSML Input -->\n  <rect x=\"14\" y=\"22\" width=\"126\" height=\"206\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"77\" y=\"42\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">1. 随钻多通道流</text>\n  <text x=\"77\" y=\"57\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"10\">WITSML 0.2–1 Hz</text>\n  <g font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#424a50\">\n    <rect x=\"24\" y=\"68\" width=\"106\" height=\"21\" rx=\"3\" fill=\"#f7ecdd\"/><text x=\"32\" y=\"82\">Torque 扭矩</text>\n    <rect x=\"24\" y=\"94\" width=\"106\" height=\"21\" rx=\"3\" fill=\"#e3efec\"/><text x=\"32\" y=\"108\">SPP 立管压力</text>\n    <rect x=\"24\" y=\"120\" width=\"106\" height=\"21\" rx=\"3\" fill=\"#e2f0e8\"/><text x=\"32\" y=\"134\">ΔQ 返出流量差</text>\n    <rect x=\"24\" y=\"146\" width=\"106\" height=\"21\" rx=\"3\" fill=\"#f6e3df\"/><text x=\"32\" y=\"160\">ΔV 泥浆池增量</text>\n    <rect x=\"24\" y=\"172\" width=\"106\" height=\"21\" rx=\"3\" fill=\"#e3ecf6\"/><text x=\"32\" y=\"186\">Hookload 大钩</text>\n    <rect x=\"24\" y=\"198\" width=\"106\" height=\"21\" rx=\"3\" fill=\"#ebe7f5\"/><text x=\"32\" y=\"212\">ROP 机械钻速</text>\n  </g>\n  <line x1=\"140\" y1=\"125\" x2=\"158\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\" marker-end=\"url(#dhw-f3-ar)\"/>\n\n  <!-- Box 2: Rig State Machine & Detrend -->\n  <rect x=\"162\" y=\"22\" width=\"136\" height=\"206\" rx=\"6\" fill=\"#ffffff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"230\" y=\"42\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"11.5\" font-weight=\"700\">2. 工况状态机过滤</text>\n  <rect x=\"172\" y=\"54\" width=\"116\" height=\"72\" rx=\"4\" fill=\"#e3efec\"/>\n  <text x=\"230\" y=\"72\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10.5\" font-weight=\"600\">大钩高度 + 泵冲判定</text>\n  <text x=\"230\" y=\"90\" text-anchor=\"middle\" fill=\"#2f7d5b\" font-size=\"10\">✓ 旋转钻进：放行</text>\n  <text x=\"230\" y=\"106\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"10\">✕ 接单根/起下钻：屏蔽</text>\n  <rect x=\"172\" y=\"136\" width=\"116\" height=\"80\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"230\" y=\"155\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10.5\" font-weight=\"600\">井深基线动态去漂移</text>\n  <text x=\"230\" y=\"173\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"10\">消除随井深增加的</text>\n  <text x=\"230\" y=\"188\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"10\">正常摩阻与循环压耗</text>\n  <text x=\"230\" y=\"206\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\">z(t)=(x-μ_d)/σ_d</text>\n  <line x1=\"298\" y1=\"125\" x2=\"316\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\" marker-end=\"url(#dhw-f3-ar)\"/>\n\n  <!-- Box 3: Temporal Autoencoder -->\n  <rect x=\"320\" y=\"22\" width=\"154\" height=\"206\" rx=\"6\" fill=\"#ffffff\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <text x=\"397\" y=\"42\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"11.5\" font-weight=\"700\">3. 时序自编码器重构</text>\n  <text x=\"397\" y=\"57\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"10\">仅用正常钻进样本训练</text>\n  <polygon points=\"334,70 368,90 368,140 334,160\" fill=\"#e3ecf6\" stroke=\"#3a6ea5\"/>\n  <text x=\"351\" y=\"119\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"600\">Encoder</text>\n  <rect x=\"376\" y=\"96\" width=\"28\" height=\"38\" rx=\"4\" fill=\"#12615a\"/>\n  <text x=\"390\" y=\"119\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"9\" font-weight=\"600\">潜空间</text>\n  <polygon points=\"412,90 446,70 446,160 412,140\" fill=\"#e3ecf6\" stroke=\"#3a6ea5\"/>\n  <text x=\"429\" y=\"119\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"600\">Decoder</text>\n  <rect x=\"332\" y=\"172\" width=\"130\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"397\" y=\"190\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10\" font-weight=\"600\">马氏重构残差 E(t)</text>\n  <text x=\"397\" y=\"206\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"10\" font-family=\"ui-monospace,Consolas,monospace\">(x-x̂)ᵀ Σ⁻¹ (x-x̂)</text>\n  <line x1=\"474\" y1=\"125\" x2=\"492\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\" marker-end=\"url(#dhw-f3-ar)\"/>\n\n  <!-- Box 4: CUSUM & Channel Attribution -->\n  <rect x=\"496\" y=\"22\" width=\"250\" height=\"206\" rx=\"6\" fill=\"#ffffff\" stroke=\"#b4483c\" stroke-width=\"1.3\"/>\n  <text x=\"621\" y=\"42\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"11.5\" font-weight=\"700\">4. CUSUM 累积触发与通道归因解释</text>\n  <rect x=\"508\" y=\"54\" width=\"226\" height=\"68\" rx=\"4\" fill=\"#f6e3df\"/>\n  <text x=\"621\" y=\"72\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"10.5\" font-weight=\"600\">CUSUM 序贯变点累积算子</text>\n  <text x=\"621\" y=\"90\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\">S(t) = max(0, S(t-1) + E(t) - k)</text>\n  <text x=\"621\" y=\"108\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">滤除单点毛刺，放大持续性前兆微漂移</text>\n  <!-- Attribution mini bars -->\n  <rect x=\"508\" y=\"130\" width=\"226\" height=\"86\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"518\" y=\"147\" fill=\"#15191c\" font-size=\"10.5\" font-weight=\"600\">通道贡献度分解 + 物理签名匹配：</text>\n  <text x=\"518\" y=\"165\" fill=\"#424a50\" font-size=\"10\">扭矩 41%</text><rect x=\"568\" y=\"156\" width=\"82\" height=\"9\" rx=\"2\" fill=\"#c27a2c\"/>\n  <text x=\"518\" y=\"181\" fill=\"#424a50\" font-size=\"10\">立压 34%</text><rect x=\"568\" y=\"172\" width=\"68\" height=\"9\" rx=\"2\" fill=\"#12615a\"/>\n  <text x=\"518\" y=\"197\" fill=\"#424a50\" font-size=\"10\">ΔQ  16%</text><rect x=\"568\" y=\"188\" width=\"32\" height=\"9\" rx=\"2\" fill=\"#2f7d5b\"/>\n  <text x=\"660\" y=\"176\" fill=\"#b4483c\" font-size=\"10.5\" font-weight=\"700\">→ 提前 15 min</text>\n  <text x=\"660\" y=\"192\" fill=\"#b4483c\" font-size=\"10.5\" font-weight=\"700\">报「卡钻前兆」</text>\n</svg></div>\n<div class=\"figcap\"><b>图 3</b><span>工况状态机过滤 + 多变量时序自编码器马氏残差 + CUSUM 累积和与通道贡献度归因的四级协同架构。</span></div>\n<div class=\"callout\"><span class=\"ci\">核心机制</span><span><strong>为什么多变量马氏残差 + CUSUM 能兼顾「零误报」与「长提前量」？</strong><br>1. <strong>工况状态机前置过滤</strong>：利用大钩位置、钻压与泥浆泵冲数实时识别「旋转钻进 / 接单根 / 起下钻 / 循环洗井」状态，在接单根瞬态窗口及开泵后 30 秒缓冲期内自动冻结异常累加器，从源头根除操作型假警报。<br>2. <strong>跨通道协方差约束</strong>：时序自编码器（TCN/LSTM-AE）仅在正常纯钻样本上训练，学习扭矩、立压、流量差与钻速之间的正常水力—机械耦合流形。当前兆萌生时，即便单个通道尚未突破极端上限，多通道联合偏离正常协方差流形也会使马氏重构误差成倍放大。<br>3. <strong>CUSUM 序贯记忆累积与物理签名归因</strong>：利用累积和（Cumulative Sum）算子滤除随机脉冲噪声、持续积分微弱趋势漂移，并通过分解各通道对重构残差的贡献占比，与三类事故的物理方向签名进行匹配，直接向司钻推送原因透明的处置建议。</span></div>"},{"no":3,"en":"","title":"需要准备什么","html":"<p>开发高可靠性的随钻复杂前兆预警系统，核心不在于追求超大规模参数量的模型，而在于<strong>高频录井时序与钻井日报复杂台账的精确对齐</strong>以及<strong>正常工况基准集的清洗</strong>：</p>\n<div class=\"checklist\"><div class=\"cl-head\"><span>数据准备清单 · 3 项</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div>\n  <div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">高频综合录井与随钻工程参数流 (WITSML)</span><span class=\"cl-s\">采样间隔 1–10 s · 至少覆盖大钩载荷、扭矩、立压、入口/出口流量、池体积、钻速 6 个核心通道，连续跨度 ≥ 15 口邻井</span></span><span class=\"cl-n\">传感器零漂校验与深度对齐</span></div>\n  <div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">钻井日报 (DDR) 与复杂事故起止台账</span><span class=\"cl-s\">精确到分钟的卡钻、井漏、溢流发生时刻、井深区间、地层层位及司钻解卡/堵漏/压井处置记录</span></span><span class=\"cl-n\">前兆回溯时间窗标注 (事故前 30 min)</span></div>\n  <div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">接单根与起下钻工况自动切分规则表</span><span class=\"cl-s\">基于大钩高度、钻头位置与泥浆泵冲数的状态转换判据，用于自动标记非纯钻瞬态时间窗</span></span><span class=\"cl-n\">状态机边界缓冲 (±30 s) 核验</span></div>\n</div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"钻井时序样本严重类别不均衡与滑窗构造示意图\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"220\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"25\" fill=\"#15191c\" font-size=\"12\" font-weight=\"700\">实钻录井样本严重类别不均衡 (99.2% : 0.6% : 0.2%) 与单类自编码滑窗构造策略</text>\n  <!-- Proportion bar -->\n  <rect x=\"18\" y=\"38\" width=\"724\" height=\"32\" rx=\"5\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <rect x=\"642\" y=\"38\" width=\"66\" height=\"32\" fill=\"#f7ecdd\" stroke=\"#c27a2c\"/>\n  <rect x=\"708\" y=\"38\" width=\"34\" height=\"32\" rx=\"3\" fill=\"#f6e3df\" stroke=\"#b4483c\"/>\n  <text x=\"320\" y=\"59\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"11.5\" font-weight=\"700\">正常钻进与常规作业段 99.2%（用于无监督/半监督重构基线训练）</text>\n  <text x=\"675\" y=\"58\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"10\" font-weight=\"700\">前兆 0.6%</text>\n  <text x=\"725\" y=\"58\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">0.2%</text>\n\n  <!-- Sliding window construction diagram -->\n  <rect x=\"18\" y=\"82\" width=\"450\" height=\"124\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"30\" y=\"102\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">多通道滑动时间窗张量构造 (Window W = 60 步 × 6 通道)</text>\n  <rect x=\"34\" y=\"114\" width=\"150\" height=\"44\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\" stroke-width=\"1.5\"/>\n  <rect x=\"94\" y=\"122\" width=\"150\" height=\"44\" rx=\"4\" fill=\"rgba(18,97,90,0.12)\" stroke=\"#12615a\" stroke-dasharray=\"4,2\"/>\n  <rect x=\"194\" y=\"130\" width=\"150\" height=\"44\" rx=\"4\" fill=\"#f7ecdd\" stroke=\"#c27a2c\" stroke-width=\"1.5\"/>\n  <text x=\"109\" y=\"140\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10\" font-weight=\"600\">正常训练窗 X_t</text>\n  <text x=\"269\" y=\"156\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"10\" font-weight=\"600\">前兆测试窗 (t-30..t min)</text>\n  <text x=\"358\" y=\"146\" fill=\"#424a50\" font-size=\"10.5\">步长 Δt = 10s</text>\n  <text x=\"358\" y=\"164\" fill=\"#737c83\" font-size=\"10\">张量维度: [B, 60, 6]</text>\n  <text x=\"34\" y=\"194\" fill=\"#737c83\" font-size=\"10\">注：直接训练二分类器极易过拟合少数事故井；采用正常工况重构 + 物理签名规则校核泛化性最佳。</text>\n\n  <!-- Right summary card -->\n  <rect x=\"480\" y=\"82\" width=\"262\" height=\"124\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"494\" y=\"102\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">台账对齐与质控三原则</text>\n  <text x=\"494\" y=\"124\" fill=\"#424a50\" font-size=\"10.5\">1. 深度—时间双索引对齐：剔除迟到时间误差</text>\n  <text x=\"494\" y=\"146\" fill=\"#424a50\" font-size=\"10.5\">2. 传感器零漂校准：每次接单根后重标定 ΔQ</text>\n  <text x=\"494\" y=\"168\" fill=\"#424a50\" font-size=\"10.5\">3. 复杂台账回溯标注：将事故前 30 min 划为</text>\n  <text x=\"494\" y=\"186\" fill=\"#c27a2c\" font-size=\"10.5\" font-weight=\"600\">   「灰区前兆过渡带」，不混入正常训练集</text>\n</svg></div>\n<div class=\"figcap\"><b>图 4</b><span>随钻时序中正常、前兆与事故样本呈现 99.2% : 0.6% : 0.2% 的极端不均衡分布，需采用正常样本重构学习结合滑窗切分。</span></div>"},{"no":4,"en":"","title":"难度与参考方向","html":"<p>在实际油田部署中，模型必须在<strong>提前预警时间（Lead Time ΔT）</strong>与<strong>百小时钻进误报率（FAR）</strong>之间取得严苛平衡。不同区块的地层岩性、泥浆体系密度与井身结构差异显著，要求模型具备极强的在线自适应基线校准能力与白盒级物理可解释性：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 235\" width=\"100%\" role=\"img\" aria-label=\"提前预警时间与误报率权衡帕累托曲线及五维技术难度\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"235\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Pareto Curve -->\n  <rect x=\"14\" y=\"14\" width=\"368\" height=\"207\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">A. 提前预警时间 ΔT vs 误报率 (FAR) 帕累托前沿</text>\n  <line x1=\"56\" y1=\"186\" x2=\"356\" y2=\"186\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"56\" y1=\"48\" x2=\"56\" y2=\"186\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"206\" y=\"208\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10.5\">每百小时钻进误报次数 FAR (次 / 100h) → 越低越好</text>\n  <text x=\"22\" y=\"118\" fill=\"#424a50\" font-size=\"10.5\" transform=\"rotate(-90 22 118)\" text-anchor=\"middle\">平均提前预警时间 ΔT (min)</text>\n  <!-- Single channel curve (lower right: poor) -->\n  <path d=\"M72,172 Q150,145 335,112\" fill=\"none\" stroke=\"#737c83\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\"/>\n  <text x=\"255\" y=\"145\" fill=\"#737c83\" font-size=\"10\">单通道阈值基线</text>\n  <!-- Multivariate + CUSUM Pareto frontier (upper left: sweet spot) -->\n  <path d=\"M68,148 Q88,68 330,54\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\"/>\n  <circle cx=\"106\" cy=\"78\" r=\"6\" fill=\"#b4483c\" stroke=\"#fff\" stroke-width=\"1.5\"/>\n  <rect x=\"116\" y=\"62\" width=\"166\" height=\"32\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"199\" y=\"76\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\">工程甜点区 (ΔT=16.5m, FAR=0.4)</text>\n  <text x=\"199\" y=\"89\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">状态机屏蔽 + 多变量 CUSUM</text>\n\n  <!-- Right: 5-D Difficulty Bars -->\n  <rect x=\"394\" y=\"14\" width=\"352\" height=\"207\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"408\" y=\"34\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">B. 井下复杂预警五维工程落地难度剖析</text>\n  <g font-size=\"10.5\" fill=\"#424a50\">\n    <text x=\"408\" y=\"62\">工况频繁切换瞬态干扰</text><rect x=\"540\" y=\"52\" width=\"160\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"540\" y=\"52\" width=\"144\" height=\"10\" rx=\"3\" fill=\"#b4483c\"/><text x=\"708\" y=\"61\" font-family=\"ui-monospace,Consolas,monospace\">9.0</text>\n    <text x=\"408\" y=\"94\">跨区块/跨地层分布漂移</text><rect x=\"540\" y=\"84\" width=\"160\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"540\" y=\"84\" width=\"136\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"93\" font-family=\"ui-monospace,Consolas,monospace\">8.5</text>\n    <text x=\"408\" y=\"126\">正负样本极端不均衡</text><rect x=\"540\" y=\"116\" width=\"160\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"540\" y=\"116\" width=\"132\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"125\" font-family=\"ui-monospace,Consolas,monospace\">8.2</text>\n    <text x=\"408\" y=\"158\">泥浆池与流量计零漂噪声</text><rect x=\"540\" y=\"148\" width=\"160\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"540\" y=\"148\" width=\"118\" height=\"10\" rx=\"3\" fill=\"#3a6ea5\"/><text x=\"708\" y=\"157\" font-family=\"ui-monospace,Consolas,monospace\">7.4</text>\n    <text x=\"408\" y=\"190\">司钻可解释性与信任建立</text><rect x=\"540\" y=\"180\" width=\"160\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"540\" y=\"180\" width=\"125\" height=\"10\" rx=\"3\" fill=\"#12615a\"/><text x=\"708\" y=\"189\" font-family=\"ui-monospace,Consolas,monospace\">7.8</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 5</b><span>提前预警时间与误报率的帕累托权衡曲线（左）及影响随钻预警系统现场投用的五维核心技术难度（右）。</span></div>\n<p>关联方法与技术方向：</p>\n<div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/ts\">多变量时序异常检测<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">时序自编码器重构残差<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">CUSUM 序贯变点检测<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">工况状态机切分与去趋势<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">通道注意力与根因归因<span class=\"ar\">↗</span></a>\n</div>"}]},"workflow":{"label":"案例流程","title":"多通道随钻前兆预警五步标准流水线","lead":["从现场 WITSML 实时录井流接入开始，依次经过工况状态机切分与接单根屏蔽、随钻井深趋势去漂移、多变量时序自编码器马氏残差计算、CUSUM 序贯变点分级触发，最终输出通道贡献度归因与司钻处置动作建议。"],"stats":[["采样频率与滑窗","0.1–1 Hz · 60 步滑窗"],["平均提前预警时间","14.5 – 19.0 min"],["纯钻与接单根误报率","≤ 0.4 次 / 100h"]],"steps":[{"name":"工况自动识别与接单根瞬态屏蔽","role":"数据","do":"读取大钩载荷、钻头深度、井深与泥浆泵冲数，采用规则状态机实时划分「旋转钻进、接单根、起下钻、循环划眼」四类工况，自动标记接单根窗口及开停泵前后 30s 瞬态缓冲期。","effect":"100% 识别接单根与停泵事件，将常规起下卡瓦、卸扣、开泵浪涌引发的操作型伪异常尖峰彻底隔离。","trap":"若仅按钻压 WOB=0 切分而忽略开泵初期立压建立的迟滞时间（约 20–40s），开泵瞬间仍会产生立压与返出流量差假警报。"},{"name":"地层趋势基线动态去漂移","role":"数据","do":"针对纯钻段各通道时序，采用 15 分钟滑动中位数滤波与指数加权移动平均（EWMA）估计当前井深下的正常摩阻与循环压耗基线 μ_d(t)，计算无量纲标准化偏离残差 z(t)。","effect":"消除随井深增加（如从 3000m 钻至 4500m）带来的大钩悬重、正常扭矩与立管压力长周期慢漂移，实现跨井段尺度归一。","trap":"滑动基线窗口不宜过短（< 5 min），否则长达 15–20 分钟的渐进性卡钻前兆爬升会被基线「同化吸收」，导致残差归零而漏报。"},{"name":"多通道自编码器重构残差计算","role":"模型","do":"将 6 通道标准化残差组装为 60 步滑动窗口张量，输入仅在正常钻进样本上训练的时序卷积自编码器（TCN-AE），计算重构误差向量的马氏距离 E(t) 与物理耦合协同项。","effect":"当多通道出现符合复杂机理的协同偏离（如扭矩↑+立压↑或 ΔQ↓+池体积↓）时，融合残差信噪比相比单通道提升 2.8 倍。","trap":"严禁把事故前 30 分钟的「前兆潜伏段」混入正常训练集，否则自编码器会学会重构早期前兆模式，大幅缩短提前预警时间。"},{"name":"CUSUM 累积和分级触发判定","role":"算法","do":"对瞬时多变量残差 E(t) 施加单边序贯累积和算子 S(t) = max(0, S(t-1) + E(t) − k)，配置黄色关注门限（0.72×阈值）与红色行动门限（阈值 θ），在接单根屏蔽期保持积分冻结衰减。","effect":"有效滤除地层软硬交界面引起的 10–20s 偶发扭矩毛刺，在事故爆发前 14–19 分钟稳定越过红警门限。","trap":"CUSUM 记忆步长与松弛常数 k 需与采样率匹配：步长过大（> 30 步）会导致突发性裂缝井漏或剧烈气侵的响应滞后 2–3 分钟。"},{"name":"通道归因解释与司钻处置建议","role":"应用","do":"在触发预警时刻，按各通道重构残差平方占比拆解根因贡献度，并与「卡钻 / 井漏 / 气侵」三类物理方向签名向量进行余弦匹配，生成分级告警卡片与首选工程处置规程。","effect":"司钻可在 3 秒内看清「为何报警、哪几个参数异常、属于哪类复杂、下一步该提钻划眼还是关井」，现场采纳率提升至 92% 以上。","trap":"不能只给一个抽象的 0–100 异常分；缺乏物理通道归因与方向校核的报警在司钻房会被视为不可信黑箱而遭到弃用。"}],"metrics":{"title":"流程分镜与验收指标","html":"<div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"五步流程分镜图：从原始录井流到提前14分钟分级预警与通道归因\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"225\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Panel 01 -->\n  <rect x=\"10\" y=\"12\" width=\"140\" height=\"201\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"29\" fill=\"#12615a\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">01</text>\n  <text x=\"36\" y=\"29\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">工况识别与屏蔽</text>\n  <rect x=\"18\" y=\"38\" width=\"124\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <rect x=\"44\" y=\"42\" width=\"16\" height=\"110\" fill=\"rgba(194,122,44,0.2)\"/>\n  <rect x=\"74\" y=\"42\" width=\"16\" height=\"110\" fill=\"rgba(194,122,44,0.2)\"/>\n  <path d=\"M22,122 L44,120 L52,54 L60,122 L74,120 L82,52 L90,122 L110,105 L136,75\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.6\"/>\n  <text x=\"80\" y=\"148\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"9.5\" font-weight=\"600\">切除 12/24m 接单根尖峰</text>\n  <text x=\"80\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">识别卡瓦与停泵瞬态</text>\n  <text x=\"80\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">消除 92% 常规作业假警报</text>\n\n  <!-- Panel 02 -->\n  <rect x=\"160\" y=\"12\" width=\"140\" height=\"201\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"168\" y=\"29\" fill=\"#12615a\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">02</text>\n  <text x=\"186\" y=\"29\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">基线动态去漂移</text>\n  <rect x=\"168\" y=\"38\" width=\"124\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <line x1=\"172\" y1=\"128\" x2=\"286\" y2=\"96\" stroke=\"#a3aab0\" stroke-width=\"1.4\" stroke-dasharray=\"3,2\"/>\n  <path d=\"M172,115 L220,115 L250,95 L286,62\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.8\"/>\n  <text x=\"230\" y=\"148\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"600\">剥离井深正常摩阻趋势</text>\n  <text x=\"230\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">滑动中位数去趋势化</text>\n  <text x=\"230\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">输出零均值标准化残差 z</text>\n\n  <!-- Panel 03 -->\n  <rect x=\"310\" y=\"12\" width=\"140\" height=\"201\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"318\" y=\"29\" fill=\"#12615a\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">03</text>\n  <text x=\"336\" y=\"29\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">多变量重构残差</text>\n  <rect x=\"318\" y=\"38\" width=\"124\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <path d=\"M322,130 L375,128 L398,108 L418,86 L436,56\" fill=\"none\" stroke=\"#3a6ea5\" stroke-width=\"1.8\"/>\n  <circle cx=\"408\" cy=\"96\" r=\"14\" fill=\"rgba(180,72,60,0.14)\" stroke=\"#b4483c\" stroke-dasharray=\"2,2\"/>\n  <text x=\"380\" y=\"148\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"600\">多通道协方差违背抬升</text>\n  <text x=\"380\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">自编码器马氏距离 E(t)</text>\n  <text x=\"380\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">捕捉多参数反常协同爬升</text>\n\n  <!-- Panel 04 -->\n  <rect x=\"460\" y=\"12\" width=\"140\" height=\"201\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"468\" y=\"29\" fill=\"#12615a\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">04</text>\n  <text x=\"486\" y=\"29\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">CUSUM 分级触发</text>\n  <rect x=\"468\" y=\"38\" width=\"124\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <line x1=\"472\" y1=\"88\" x2=\"588\" y2=\"88\" stroke=\"#b4483c\" stroke-dasharray=\"4,2\"/>\n  <line x1=\"472\" y1=\"108\" x2=\"588\" y2=\"108\" stroke=\"#c27a2c\" stroke-dasharray=\"3,2\"/>\n  <path d=\"M472,134 L522,132 L542,108 L556,88 L584,52\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.2\"/>\n  <circle cx=\"556\" cy=\"88\" r=\"4.5\" fill=\"#b4483c\"/>\n  <text x=\"530\" y=\"148\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">提前 15.3 min 触发红警</text>\n  <text x=\"530\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">序贯累积抑制瞬时毛刺</text>\n  <text x=\"530\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">黄/红双阈值锁定时间窗</text>\n\n  <!-- Panel 05 -->\n  <rect x=\"610\" y=\"12\" width=\"140\" height=\"201\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"618\" y=\"29\" fill=\"#12615a\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">05</text>\n  <text x=\"636\" y=\"29\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">通道归因与处置</text>\n  <rect x=\"618\" y=\"38\" width=\"124\" height=\"118\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"624\" y=\"58\" fill=\"#424a50\" font-size=\"9.5\">扭矩↑</text><rect x=\"656\" y=\"50\" width=\"68\" height=\"9\" rx=\"2\" fill=\"#c27a2c\"/>\n  <text x=\"624\" y=\"78\" fill=\"#424a50\" font-size=\"9.5\">立压↑</text><rect x=\"656\" y=\"70\" width=\"54\" height=\"9\" rx=\"2\" fill=\"#12615a\"/>\n  <text x=\"624\" y=\"98\" fill=\"#424a50\" font-size=\"9.5\">ΔQ ↘</text><rect x=\"656\" y=\"90\" width=\"28\" height=\"9\" rx=\"2\" fill=\"#2f7d5b\"/>\n  <rect x=\"624\" y=\"112\" width=\"112\" height=\"34\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"680\" y=\"126\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"9.5\" font-weight=\"700\">诊断：岩屑床卡钻 94%</text>\n  <text x=\"680\" y=\"140\" text-anchor=\"middle\" fill=\"#15191c\" font-size=\"9\">建议：停钻划眼+大排量洗井</text>\n  <text x=\"680\" y=\"176\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"10\">输出根因通道与处置卡</text>\n  <text x=\"680\" y=\"192\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"9.5\">辅助司钻在黄金窗内解危</text>\n</svg></div>\n<div class=\"figcap\"><b>图 6</b><span>五步前兆预警流水线分镜：从 60 分钟含接单根干扰的原始多通道录井曲线到提前 15 分钟发出可解释红警。</span></div>\n\n<div class=\"figure\"><svg viewBox=\"0 0 760 190\" width=\"100%\" role=\"img\" aria-label=\"井下复杂事故前兆预警核心验收指标示意图\">\n  <rect x=\"0\" y=\"0\" width=\"760\" height=\"190\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Lead Time Window -->\n  <rect x=\"12\" y=\"12\" width=\"440\" height=\"166\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"24\" y=\"32\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">核心验收指标 1：有效提前预警时间窗 ΔT_lead = t_incident − t_alarm</text>\n  <line x1=\"36\" y1=\"126\" x2=\"428\" y2=\"126\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n  <!-- Timeline markers -->\n  <circle cx=\"96\" cy=\"126\" r=\"5\" fill=\"#c27a2c\"/>\n  <text x=\"96\" y=\"146\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"10\" font-weight=\"600\">前兆萌生 t_0</text>\n  <circle cx=\"196\" cy=\"126\" r=\"6\" fill=\"#12615a\"/>\n  <text x=\"196\" y=\"146\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"10\" font-weight=\"700\">预警触发 t_alarm</text>\n  <circle cx=\"366\" cy=\"126\" r=\"6\" fill=\"#b4483c\"/>\n  <text x=\"366\" y=\"146\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"700\">复杂爆发 t_incident</text>\n  <!-- Bracket for Lead Time -->\n  <rect x=\"174\" y=\"60\" width=\"214\" height=\"46\" rx=\"5\" fill=\"#e3efec\" stroke=\"#12615a\" stroke-width=\"1.4\"/>\n  <text x=\"281\" y=\"79\" text-anchor=\"middle\" fill=\"#12615a\" font-size=\"11\" font-weight=\"700\">有效提前量 ΔT_lead ∈ [10, 25] min</text>\n  <text x=\"281\" y=\"96\" text-anchor=\"middle\" fill=\"#424a50\" font-size=\"9.5\">预留充足司钻停钻、划眼、关井或堵漏时间</text>\n  <text x=\"24\" y=\"168\" fill=\"#737c83\" font-size=\"9.5\">判据：ΔT_lead &lt; 5 min 视为预警过晚（来不及处置）；&gt; 45 min 且无机理支撑视为早期误报。</text>\n\n  <!-- Right: Event Recall & FAR per 100h -->\n  <rect x=\"464\" y=\"12\" width=\"284\" height=\"166\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e7e3da\"/>\n  <text x=\"478\" y=\"32\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"700\">核心验收指标 2 &amp; 3：事件召回率与百小时误报</text>\n  <rect x=\"478\" y=\"44\" width=\"256\" height=\"54\" rx=\"5\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"490\" y=\"64\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">事件级召回率 Event Recall ≥ 90%</text>\n  <text x=\"490\" y=\"84\" fill=\"#424a50\" font-size=\"10\">在事故发生前 [5, 35] min 窗口内成功触发红警占比</text>\n  <rect x=\"478\" y=\"108\" width=\"256\" height=\"58\" rx=\"5\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"490\" y=\"128\" fill=\"#15191c\" font-size=\"11\" font-weight=\"700\">百小时钻进误报率 FAR ≤ 0.5 次 / 100h</text>\n  <text x=\"490\" y=\"148\" fill=\"#424a50\" font-size=\"10\">接单根、划眼、开停泵期间误触发次数必须趋近于 0</text>\n</svg></div>\n<div class=\"figcap\"><b>图 7</b><span>井下复杂预警系统的三维工程验收标准：有效提前预警时间 ΔT_lead、事件级召回率与每百小时钻进误报率。</span></div>"},"fails":[{"name":"未做接单根与开停泵工况切分即直接训练全井段模型","why":"正常接单根时大钩载荷、立压与扭矩的变动幅度远超早期复杂前兆，模型会将 90% 的容量用于拟合接单根阶跃，或在实际运行时每打完一根单根（约 30–45 分钟）就误报一次。"},{"name":"去趋势滑窗过短导致渐进式卡钻前兆被基线「吞噬」","why":"岩屑床堆积卡钻的前兆往往表现为长达 15–25 分钟的扭矩与立压温和爬升；若动态基线更新过快，模型会把前兆爬升误认为新的正常地层基线，直到卡死瞬间才报警。"},{"name":"泥浆池液位与出口流量计受钻井船摇摆或沉砂干扰未做交叉校核","why":"单一出口流量计或池液位计极易受振动与浮子卡滞影响；必须结合立压（SPP）、机械钻速突增（Drilling Break）与流量差 ΔQ 进行多通道耦合校核，才能避免虚假溢流/井漏报警。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":760}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>多通道随钻时序井下复杂事故前兆预警</title>\n  <link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<div class=\"app\">\n  <header class=\"topbar\">\n    <h1>多通道随钻时序井下复杂事故前兆预警</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pill-rig\"><i></i><span id=\"pill-rig-txt\">当前游标工况：正常旋转钻进</span></span>\n    <span class=\"pill ok\" id=\"pill-warn\"><i></i><span id=\"pill-warn-txt\">前兆捕捉：提前 15.3 min 触发红警</span></span>\n  </header>\n\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步进\">\n    <button type=\"button\" data-step=\"1\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">工况自动识别与接单根瞬态屏蔽</span>\n    </button>\n    <button type=\"button\" data-step=\"2\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">地层趋势基线动态去漂移</span>\n    </button>\n    <button type=\"button\" data-step=\"3\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">多通道自编码器重构残差计算</span>\n    </button>\n    <button type=\"button\" data-step=\"4\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">CUSUM 累积和分级触发判定</span>\n    </button>\n    <button type=\"button\" data-step=\"5\" class=\"on\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">通道归因解释与司钻处置建议</span>\n    </button>\n  </nav>\n\n  <div class=\"bench\">\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>1. 实钻前兆工况序列 (60 min)</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">10s 采样</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ep-list\" id=\"ep-list\">\n            <button type=\"button\" class=\"ep-btn on\" data-ep=\"sticking\">\n              <div class=\"ep-t\"><span>渐进性岩屑床卡钻</span><span class=\"ep-badge\">Pack-off</span></div>\n              <div class=\"ep-s\">12/24 min 接单根瞬态；28 min 起扭矩与立压爬升、返出微降，50 min 卡钻</div>\n            </button>\n            <button type=\"button\" class=\"ep-btn\" data-ep=\"lost\">\n              <div class=\"ep-t\"><span>裂缝性井漏前兆</span><span class=\"ep-badge\">Lost Circ.</span></div>\n              <div class=\"ep-s\">30 min 钻遇微裂缝带，返出流量差 ΔQ 骤降为负，泥浆池减量与立压缓降</div>\n            </button>\n            <button type=\"button\" class=\"ep-btn\" data-ep=\"kick\">\n              <div class=\"ep-t\"><span>高压层气侵溢流前兆</span><span class=\"ep-badge\">Gas Kick</span></div>\n              <div class=\"ep-s\">26 min 钻速突增 (Drilling Break)，随后环空气侵导致 ΔQ &gt; 0 与池体积抬升</div>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>2. 异常检测算子与模型参数</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时重算</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\"><span>检测模式对比</span></div>\n            <div class=\"mode-seg\" id=\"mode-seg\">\n              <button type=\"button\" data-mode=\"single\">\n                <span>单通道固定阈值</span><span class=\"m-tag\">传统基线</span>\n              </button>\n              <button type=\"button\" data-mode=\"mahal\">\n                <span>多变量马氏残差</span><span class=\"m-tag\">瞬时重构</span>\n              </button>\n              <button type=\"button\" data-mode=\"cusum\" class=\"on\">\n                <span>多变量残差 + CUSUM 滤波</span><span class=\"m-tag\">AI 推荐</span>\n              </button>\n            </div>\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <label for=\"sl-thresh\">报警触发阈值 (红警门限)</label>\n              <output id=\"val-thresh\">3.2 σ</output>\n            </div>\n            <input type=\"range\" id=\"sl-thresh\" min=\"1.8\" max=\"5.5\" step=\"0.1\" value=\"3.2\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <label for=\"sl-cusum\">CUSUM 平滑记忆步长</label>\n              <output id=\"val-cusum\">8 步 (80s)</output>\n            </div>\n            <input type=\"range\" id=\"sl-cusum\" min=\"1\" max=\"18\" step=\"1\" value=\"8\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <label for=\"sl-noise\">传感器背景噪声强度</label>\n              <output id=\"val-noise\">0.60×</output>\n            </div>\n            <input type=\"range\" id=\"sl-noise\" min=\"0.2\" max=\"2.0\" step=\"0.1\" value=\"0.6\">\n          </div>\n\n          <div class=\"divider\"></div>\n\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-mask\" checked>\n            <span>启用接单根工况自动屏蔽（消除 12/24 min 假警报！）</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-zone\" checked>\n            <span>显示前兆演化区间与提前量 ΔT</span>\n          </label>\n\n          <div class=\"btn-row\">\n            <button type=\"button\" class=\"btn primary\" id=\"btn-play\">▶ 巡检回放</button>\n            <button type=\"button\" class=\"btn\" id=\"btn-reset\">↺ 重置默认</button>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <main class=\"stage\">\n      <div class=\"view\">\n        <div class=\"view-h\">\n          <span id=\"stage-title\">五道随钻工程参数同步录井联图与融合前兆指数 (0–60 min · 360 步)</span>\n          <span class=\"sp\"></span>\n          <div class=\"legend\">\n            <span><i style=\"background:rgba(194,122,44,.22);border:1px solid #c27a2c\"></i>接单根瞬态窗口</span>\n            <span><i style=\"background:rgba(180,72,60,.14);border:1px dashed #b4483c\"></i>前兆潜伏演化段</span>\n            <span><i class=\"line\" style=\"background:#12615a\"></i>AI 融合指数 S(t)</span>\n            <span><i class=\"dash\" style=\"color:#737c83\"></i>单通道最大超限比</span>\n          </div>\n        </div>\n\n        <svg id=\"strip-svg\" class=\"strip-svg\" viewBox=\"0 0 840 465\" width=\"100%\" role=\"img\" aria-label=\"多通道随钻时序联图\"></svg>\n        <div class=\"tip\" id=\"strip-tip\"></div>\n\n        <div class=\"scrub-bar\">\n          <span class=\"lbl\">时间游标定位 (拖拽画布或滑杆)：</span>\n          <input type=\"range\" id=\"sl-cursor\" min=\"0\" max=\"359\" step=\"1\" value=\"234\">\n          <span class=\"t-readout\" id=\"txt-cursor\">t = 39.0 min (步 #234)</span>\n        </div>\n      </div>\n    </main>\n  </div>\n\n  <section class=\"kpis\" style=\"margin-top:14px\">\n    <div class=\"kpi ok\" id=\"kpi-lead\">\n      <div class=\"k\">提前预警时间 ΔT (min)</div>\n      <div class=\"v\" id=\"kpi-lead-v\">15.3<small>min</small></div>\n      <div class=\"d\" id=\"kpi-lead-d\">红警触发 t=34.7 min（事故 50.0 min）</div>\n    </div>\n    <div class=\"kpi ok\" id=\"kpi-far\">\n      <div class=\"k\">工况期间误报次数</div>\n      <div class=\"v\" id=\"kpi-far-v\">0<small>次</small></div>\n      <div class=\"d\" id=\"kpi-far-d\">接单根瞬态已被状态机自动屏蔽</div>\n    </div>\n    <div class=\"kpi acc\" id=\"kpi-type\">\n      <div class=\"k\">判定事故类型与置信度</div>\n      <div class=\"v text-v\" id=\"kpi-type-v\">岩屑床卡钻 · 94%</div>\n      <div class=\"d\" id=\"kpi-type-d\">扭矩↑ + 立压↑ + 返出微降耦合匹配</div>\n    </div>\n    <div class=\"kpi warn\" id=\"kpi-act\">\n      <div class=\"k\">首选司钻处置建议</div>\n      <div class=\"v text-v\" id=\"kpi-act-v\">上提划眼 + 大排量洗井</div>\n      <div class=\"d\" id=\"kpi-act-d\">立即停止进尺，循环携砂清洁环空</div>\n    </div>\n  </section>\n\n  <div class=\"grid2\" style=\"margin-top:14px\">\n    <div class=\"view\">\n      <div class=\"view-h\">\n        <span>游标时刻通道异常贡献度归因与三类事故模式匹配度</span>\n        <span class=\"sp\"></span>\n        <span class=\"mono muted small\" id=\"attr-time-tag\">@ t = 39.0 min</span>\n      </div>\n      <svg id=\"aux-attr-svg\" viewBox=\"0 0 420 250\" width=\"100%\" role=\"img\" aria-label=\"通道异常贡献度归因与事故匹配概率\"></svg>\n    </div>\n\n    <div class=\"view\">\n      <div class=\"view-h\">\n        <span>井筒环空实时状态剖面与阈值灵敏度（ΔT vs 误报）权衡曲线</span>\n        <span class=\"sp\"></span>\n        <span class=\"mono muted small\" id=\"well-depth-tag\">井深 3482 m</span>\n      </div>\n      <svg id=\"aux-well-svg\" viewBox=\"0 0 420 250\" width=\"100%\" role=\"img\" aria-label=\"井筒实时状态与阈值权衡曲线\"></svg>\n    </div>\n  </div>\n\n  <div class=\"insight\" id=\"insight-box\" style=\"margin-top:14px\">\n    <div class=\"tag\" id=\"insight-tag\">实时机理诊断</div>\n    <div id=\"insight-txt\">正在加载随钻多通道遥测序列与 CUSUM 诊断结果……</div>\n  </div>\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":9078},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* ---------- 钻井复杂事故前兆预警工作台专属样式 ---------- */\n.ep-list{display:flex;flex-direction:column;gap:6px}\n.ep-btn{all:unset;cursor:pointer;display:flex;flex-direction:column;gap:2px;padding:8px 10px;border-radius:8px;\n  border:1px solid var(--line);background:var(--paper);transition:all .15s}\n.ep-btn:hover{border-color:var(--ink-4);background:var(--surface)}\n.ep-btn.on{border-color:var(--accent);background:var(--accent-l)}\n.ep-btn .ep-t{font-size:12px;font-weight:650;color:var(--ink);display:flex;align-items:center;justify-content:space-between}\n.ep-btn.on .ep-t{color:var(--accent)}\n.ep-btn .ep-s{font-size:11px;color:var(--ink-3);line-height:1.4}\n.ep-badge{font-family:var(--mono);font-size:10px;padding:1px 6px;border-radius:99px;background:var(--surface);border:1px solid var(--line-2);color:var(--ink-2)}\n\n.mode-seg{display:flex;flex-direction:column;gap:4px}\n.mode-seg button{all:unset;cursor:pointer;padding:6px 10px;border-radius:7px;font-size:11.5px;border:1px solid var(--line);\n  background:var(--paper);color:var(--ink-2);display:flex;align-items:center;justify-content:space-between;transition:all .15s}\n.mode-seg button:hover{border-color:var(--ink-3)}\n.mode-seg button.on{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}\n.mode-seg button .m-tag{font-size:10px;opacity:.85;font-family:var(--mono)}\n\n.scrub-bar{display:flex;align-items:center;gap:10px;padding:8px 14px;background:var(--paper);border-top:1px solid var(--line);font-size:11.5px}\n.scrub-bar .lbl{font-weight:600;color:var(--ink-2);white-space:nowrap}\n.scrub-bar input[type=range]{flex:1}\n.scrub-bar .t-readout{font-family:var(--mono);font-weight:600;color:var(--accent);min-width:110px;text-align:right}\n\n.btn-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}\n.kpi .v.text-v{font-family:var(--sans);font-size:15px;font-weight:700;letter-spacing:0}\n.strip-svg{cursor:crosshair;user-select:none}\n","enc":"text","size":12492},{"name":"demo/demo.js","data":"(function () {\n  'use strict';\n\n  const N = 360; // 60 min @ 10s resolution (0..359)\n  const DT_MIN = 1 / 6; // 10s = 1/6 min\n\n  // Fixed seed PRNG\n  function mulberry32(seed) {\n    let a = seed >>> 0;\n    return function () {\n      a |= 0;\n      a = (a + 0x6D2B79F5) | 0;\n      let t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n\n  function randn(rng) {\n    const u1 = Math.max(1e-7, rng());\n    const u2 = rng();\n    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);\n  }\n\n  const EPISODES = {\n    sticking: {\n      id: 'sticking',\n      name: '渐进性岩屑床卡钻',\n      precursorIdx: 168, // 28.0 min\n      incidentIdx: 300,  // 50.0 min\n      baseDepth: 3465,\n      trueLabel: '岩屑床卡钻',\n      advice: '上提划眼 + 大排量洗井',\n      adviceSub: '立即停止进尺，循环携砂清洁环空',\n      connWindows: [\n        [70, 77],   // ~11.7 - 12.8 min\n        [142, 149]  // ~23.7 - 24.8 min\n      ]\n    },\n    lost: {\n      id: 'lost',\n      name: '裂缝性井漏前兆',\n      precursorIdx: 180, // 30.0 min\n      incidentIdx: 300,  // 50.0 min\n      baseDepth: 3810,\n      trueLabel: '裂缝性井漏',\n      advice: '降排量 + 注入随钻堵漏剂(LCM)',\n      adviceSub: '降低环空动压耗，防止诱导裂缝扩展',\n      connWindows: [\n        [70, 77],\n        [142, 149]\n      ]\n    },\n    kick: {\n      id: 'kick',\n      name: '高压层气侵溢流前兆',\n      precursorIdx: 156, // 26.0 min\n      incidentIdx: 300,  // 50.0 min\n      baseDepth: 4120,\n      trueLabel: '高压层气侵溢流',\n      advice: '停钻抢关井 + 循环加重压井',\n      adviceSub: '立即执行硬关井程序，记录立管与套管关井压力',\n      connWindows: [\n        [70, 77],\n        [142, 149]\n      ]\n    }\n  };\n\n  const state = {\n    ep: 'sticking',\n    mode: 'cusum',      // 'single' | 'mahal' | 'cusum'\n    step: 5,            // 1..5\n    thresh: 3.2,\n    cusumWin: 8,\n    noise: 0.6,\n    maskConn: true,\n    showZone: true,\n    cursor: 234,        // 39.0 min\n    playing: false,\n    playTimer: null,\n    sim: null\n  };\n\n  function isConnIdx(epCfg, i) {\n    for (let k = 0; k < epCfg.connWindows.length; k++) {\n      const w = epCfg.connWindows[k];\n      if (i >= w[0] && i <= w[1]) return true;\n    }\n    return false;\n  }\n\n  function simulateEpisode() {\n    const epCfg = EPISODES[state.ep];\n    const rng = mulberry32(state.ep === 'sticking' ? 20261101 : state.ep === 'lost' ? 20261102 : 20261103);\n    const nz = state.noise;\n\n    const tMin = new Float64Array(N);\n    const connFlag = new Uint8Array(N);\n    // Raw channels\n    const hkld = new Float64Array(N); // kN (normal ~1120)\n    const rop  = new Float64Array(N); // m/h (normal ~14.5)\n    const torq = new Float64Array(N); // kN·m (normal ~18.5)\n    const spp  = new Float64Array(N); // MPa (normal ~24.0)\n    const dq   = new Float64Array(N); // L/s (normal ~0.0)\n    const dv   = new Float64Array(N); // m³ (normal ~0.0)\n\n    // Expected normal baselines (formation drift included)\n    const bHkld = new Float64Array(N);\n    const bRop  = new Float64Array(N);\n    const bTorq = new Float64Array(N);\n    const bSpp  = new Float64Array(N);\n\n    // Normalized channel z-residuals (after rig-state filter & detrend)\n    const zCh = [\n      new Float64Array(N), // 0: Torque\n      new Float64Array(N), // 1: SPP\n      new Float64Array(N), // 2: dQ\n      new Float64Array(N), // 3: dV\n      new Float64Array(N), // 4: Hookload\n      new Float64Array(N)  // 5: ROP\n    ];\n\n    const singleScore = new Float64Array(N);\n    const mahalScore  = new Float64Array(N);\n    const cusumScore  = new Float64Array(N);\n    const activeScore = new Float64Array(N);\n\n    let cumPit = 0;\n\n    for (let i = 0; i < N; i++) {\n      const m = i * DT_MIN;\n      tMin[i] = m;\n      const inConn = isConnIdx(epCfg, i);\n      connFlag[i] = inConn ? 1 : 0;\n\n      // Gentle formation depth trend\n      bHkld[i] = 1115 + 0.35 * m;\n      bRop[i]  = 14.2 - 0.03 * m;\n      bTorq[i] = 18.2 + 0.04 * m;\n      bSpp[i]  = 23.8 + 0.025 * m;\n\n      let h = bHkld[i] + randn(rng) * 9.0 * nz;\n      let r = bRop[i]  + randn(rng) * 0.75 * nz;\n      let tq = bTorq[i] + randn(rng) * 0.65 * nz;\n      let sp = bSpp[i]  + randn(rng) * 0.38 * nz;\n      let q  = randn(rng) * 0.42 * nz;\n      let v  = cumPit + randn(rng) * 0.06 * nz;\n\n      // Pipe connection transient (12 min & 24 min): slips set, pump off/on, torque spike, hookload jump\n      if (inConn) {\n        const phase = (i - (i < 100 ? 70 : 142)) / 7;\n        h += 145 * Math.sin(phase * Math.PI);      // Hoisting string\n        r = 0.8 + Math.abs(randn(rng)) * 0.3;      // Bit off bottom\n        tq += 8.6 * Math.sin(phase * Math.PI * 2); // Breakout/makeup & reaming spike\n        sp -= 9.5 * Math.sin(phase * Math.PI);     // Pump ramp down/up\n        q  -= 4.8 * Math.cos(phase * Math.PI);     // Annular return surge/drop\n      }\n\n      // Precursor & incident physics\n      if (i >= epCfg.precursorIdx) {\n        const u = Math.min(1.32, (i - epCfg.precursorIdx) / (epCfg.incidentIdx - epCfg.precursorIdx));\n        const ramp = Math.pow(u, 1.35);\n\n        if (state.ep === 'sticking') {\n          // Pack-off pipe sticking: Torque ↑↑, SPP ↑↑, Hookload drag ↑, dQ slight ↓, ROP ↓\n          const stickSpike = 0.8 * Math.sin(i * 0.65) * u;\n          tq += 9.8 * ramp + stickSpike * 2.2;\n          sp += 5.4 * ramp + Math.max(0, stickSpike) * 1.1;\n          h  += 72 * ramp;\n          q  -= 2.1 * ramp;\n          r  -= 6.5 * ramp;\n          cumPit -= 0.0045 * ramp;\n          v = cumPit + randn(rng) * 0.05 * nz;\n          if (i >= epCfg.incidentIdx) {\n            r = 0.2;\n            tq += 4.2;\n            sp += 2.4;\n          }\n        } else if (state.ep === 'lost') {\n          // Lost circulation: dQ ↓↓, Pit dV ↓↓, SPP ↓, Torque slight fluctuation\n          q  -= 7.8 * ramp;\n          cumPit -= 0.036 * ramp;\n          v = cumPit + randn(rng) * 0.05 * nz;\n          sp -= 3.9 * ramp;\n          h  += 22 * ramp;\n          tq += 1.4 * ramp;\n        } else if (state.ep === 'kick') {\n          // Gas kick: Drilling break (ROP jump first), then dQ ↑↑, Pit dV ↑↑, SPP ↓ (gas cut mud)\n          const breakBoost = u < 0.35 ? 7.2 * Math.sin((u / 0.35) * Math.PI) : 3.2;\n          r  += breakBoost;\n          q  += 8.2 * Math.pow(Math.max(0, u - 0.06), 1.25);\n          cumPit += 0.038 * Math.pow(Math.max(0, u - 0.06), 1.25);\n          v = cumPit + randn(rng) * 0.05 * nz;\n          sp -= 2.6 * ramp;\n          h  -= 28 * ramp;\n        }\n      }\n\n      hkld[i] = h;\n      rop[i]  = Math.max(0.1, r);\n      torq[i] = Math.max(1.0, tq);\n      spp[i]  = Math.max(2.0, sp);\n      dq[i]   = q;\n      dv[i]   = v;\n\n      // Standardized deviations from formation trend baseline\n      let zTorq = (torq[i] - bTorq[i]) / 1.15;\n      let zSpp  = (spp[i]  - bSpp[i])  / 0.68;\n      let zDq   = dq[i] / 0.85;\n      let zDv   = dv[i] / 0.42;\n      let zHkld = (hkld[i] - bHkld[i]) / 16.0;\n      let zRop  = (rop[i]  - bRop[i])  / 1.55;\n\n      // Single-channel raw max excursion (if not masked during connection, spikes hard at 12/24 min)\n      const maskFactor = (inConn && state.maskConn) ? 0.12 : 1.0;\n\n      zCh[0][i] = zTorq * maskFactor;\n      zCh[1][i] = zSpp  * maskFactor;\n      zCh[2][i] = zDq   * maskFactor;\n      zCh[3][i] = zDv   * maskFactor;\n      zCh[4][i] = zHkld * maskFactor;\n      zCh[5][i] = zRop  * maskFactor;\n\n      // Single-channel score: max absolute z among primary channels (sensitive to connection & random spikes)\n      const rawMaxZ = Math.max(\n        Math.abs(zTorq),\n        Math.abs(zSpp),\n        Math.abs(zDq),\n        Math.abs(zHkld) * 0.95\n      );\n      singleScore[i] = (inConn && state.maskConn) ? rawMaxZ * 0.22 : rawMaxZ * 0.86;\n\n      // Multivariate Autoencoder Mahalanobis residual: captures cross-channel coupling\n      const a0 = zCh[0][i], a1 = zCh[1][i], a2 = zCh[2][i], a3 = zCh[3][i], a4 = zCh[4][i], a5 = zCh[5][i];\n      // Coupling synergy boost when channels move in physically consistent hazard pattern\n      let synergy = 0;\n      if (a0 > 0.7 && a1 > 0.7) synergy += 0.45 * Math.sqrt(a0 * a1); // Sticking coupling\n      if (a2 < -0.7 && a3 < -0.4 && a1 < -0.4) synergy += 0.55 * Math.sqrt(Math.abs(a2 * a3)); // Lost circ coupling\n      if (a2 > 0.7 && a3 > 0.4 && a5 > 0.5) synergy += 0.55 * Math.sqrt(Math.abs(a2 * a3)); // Kick coupling\n\n      const rmsZ = Math.sqrt((a0 * a0 * 1.25 + a1 * a1 * 1.15 + a2 * a2 * 1.25 + a3 * a3 * 1.0 + a4 * a4 * 0.7 + a5 * a5 * 0.65) / 4.2);\n      mahalScore[i] = rmsZ + synergy;\n    }\n\n    // Step 4: CUSUM / EWMA memory accumulation over window `state.cusumWin`\n    const w = state.cusumWin;\n    const alpha = 2 / (w + 1);\n    const driftSlack = 0.72 + 0.18 * nz;\n    let cAcc = 0;\n    for (let i = 0; i < N; i++) {\n      if (connFlag[i] && state.maskConn) {\n        cAcc *= 0.65;\n      } else {\n        const inc = mahalScore[i] - driftSlack;\n        cAcc = Math.max(0, cAcc * (1 - alpha * 0.55) + inc * (0.42 + 0.58 * alpha));\n      }\n      cusumScore[i] = Math.min(9.5, 0.55 * mahalScore[i] + 0.92 * cAcc);\n\n      if (state.mode === 'single') activeScore[i] = singleScore[i];\n      else if (state.mode === 'mahal') activeScore[i] = mahalScore[i];\n      else activeScore[i] = cusumScore[i];\n    }\n\n    // Evaluate alarm metrics under current threshold\n    const metrics = evaluateAlarmMetrics(epCfg, activeScore, state.thresh);\n\n    state.sim = {\n      epCfg,\n      tMin,\n      connFlag,\n      hkld, rop, torq, spp, dq, dv,\n      bHkld, bRop, bTorq, bSpp,\n      zCh,\n      singleScore,\n      mahalScore,\n      cusumScore,\n      activeScore,\n      metrics\n    };\n  }\n\n  function evaluateAlarmMetrics(epCfg, scoreArr, th) {\n    let falseAlarms = 0;\n    let inFaCluster = false;\n    let faCooldown = 0;\n    const faIndices = [];\n\n    for (let i = 0; i < epCfg.precursorIdx; i++) {\n      if (scoreArr[i] >= th) {\n        if (!inFaCluster && faCooldown <= 0) {\n          falseAlarms++;\n          faIndices.push(i);\n          inFaCluster = true;\n          faCooldown = 4; // group spikes within 40s as one alarm event\n        }\n      } else {\n        inFaCluster = false;\n        if (faCooldown > 0) faCooldown--;\n      }\n    }\n\n    let alarmIdx = -1;\n    for (let i = epCfg.precursorIdx; i <= epCfg.incidentIdx; i++) {\n      if (scoreArr[i] >= th) {\n        alarmIdx = i;\n        break;\n      }\n    }\n\n    let yellowIdx = -1;\n    const yellowTh = th * 0.72;\n    for (let i = epCfg.precursorIdx; i <= epCfg.incidentIdx; i++) {\n      if (scoreArr[i] >= yellowTh) {\n        yellowIdx = i;\n        break;\n      }\n    }\n\n    const leadMin = alarmIdx >= 0 ? (epCfg.incidentIdx - alarmIdx) * DT_MIN : 0;\n    return {\n      falseAlarms,\n      faIndices,\n      alarmIdx,\n      yellowIdx,\n      yellowTh,\n      leadMin\n    };\n  }\n\n  function updateRangeProgress(el) {\n    const min = parseFloat(el.min) || 0;\n    const max = parseFloat(el.max) || 100;\n    const val = parseFloat(el.value) || 0;\n    const pct = ((val - min) / (max - min)) * 100;\n    el.style.setProperty('--p', pct.toFixed(1) + '%');\n  }\n\n  function buildPath(arr, x0, xW, y0, yH, vMin, vMax) {\n    let d = '';\n    const span = (vMax - vMin) || 1;\n    for (let i = 0; i < N; i++) {\n      const x = x0 + (i / (N - 1)) * xW;\n      const clamped = Math.max(vMin, Math.min(vMax, arr[i]));\n      const y = y0 + yH - ((clamped - vMin) / span) * yH;\n      d += (i === 0 ? 'M' : 'L') + x.toFixed(1) + ',' + y.toFixed(1);\n    }\n    return d;\n  }\n\n  function renderStripChart() {\n    const svg = document.getElementById('strip-svg');\n    const sim = state.sim;\n    const ep = sim.epCfg;\n    const x0 = 96, xW = 724, x1 = x0 + xW;\n\n    const tracks = [\n      { title: '大钩载荷 / 钻速', unit: 'kN | m/h', y0: 16, yH: 66 },\n      { title: '转盘扭矩 Torq',   unit: 'kN·m',     y0: 94, yH: 66 },\n      { title: '立管压力 SPP',    unit: 'MPa',      y0: 172, yH: 66 },\n      { title: '流量差 / 池增量', unit: 'L/s | m³', y0: 250, yH: 66 },\n      { title: '融合前兆指数 S(t)', unit: 'σ 等效值', y0: 328, yH: 98 }\n    ];\n\n    let html = `<defs>\n      <linearGradient id=\"dhw-demo-score-grad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n        <stop offset=\"0%\" stop-color=\"#b4483c\" stop-opacity=\"0.32\"/>\n        <stop offset=\"55%\" stop-color=\"#c27a2c\" stop-opacity=\"0.18\"/>\n        <stop offset=\"100%\" stop-color=\"#12615a\" stop-opacity=\"0.03\"/>\n      </linearGradient>\n    </defs>`;\n\n    // Track backgrounds & horizontal grid lines\n    tracks.forEach((tr, idx) => {\n      const highlightTrack = (state.step === 2 && (idx === 1 || idx === 2)) || (state.step === 3 && idx === 4) || (state.step === 4 && idx === 4);\n      const bgFill = highlightTrack ? '#f6fbf9' : '#fbfaf7';\n      html += `<rect x=\"${x0}\" y=\"${tr.y0}\" width=\"${xW}\" height=\"${tr.yH}\" rx=\"4\" fill=\"${bgFill}\" stroke=\"#e7e3da\" stroke-width=\"1\"/>`;\n      html += `<line x1=\"${x0}\" y1=\"${tr.y0 + tr.yH / 2}\" x2=\"${x1}\" y2=\"${tr.y0 + tr.yH / 2}\" stroke=\"#ece8df\" stroke-dasharray=\"3,3\"/>`;\n      html += `<text x=\"10\" y=\"${tr.y0 + 25}\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"600\">${tr.title}</text>`;\n      html += `<text x=\"10\" y=\"${tr.y0 + 43}\" fill=\"#737c83\" font-size=\"10.5\" font-family=\"ui-monospace,Consolas,monospace\">${tr.unit}</text>`;\n    });\n\n    // Vertical time grid every 10 min\n    for (let m = 0; m <= 60; m += 10) {\n      const gx = x0 + (m / 60) * xW;\n      html += `<line x1=\"${gx.toFixed(1)}\" y1=\"16\" x2=\"${gx.toFixed(1)}\" y2=\"426\" stroke=\"#eae6dc\" stroke-width=\"1\"/>`;\n      html += `<text x=\"${gx.toFixed(1)}\" y=\"446\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"11\" font-family=\"ui-monospace,Consolas,monospace\">${m} min</text>`;\n    }\n\n    // Connection transient bands (12 min & 24 min)\n    ep.connWindows.forEach((w, idx) => {\n      const cx0 = x0 + (w[0] / (N - 1)) * xW;\n      const cxW = Math.max(8, ((w[1] - w[0]) / (N - 1)) * xW);\n      const bandColor = state.maskConn ? 'rgba(18,97,90,0.10)' : 'rgba(194,122,44,0.20)';\n      const strokeColor = state.maskConn ? '#12615a' : '#c27a2c';\n      html += `<rect x=\"${cx0.toFixed(1)}\" y=\"16\" width=\"${cxW.toFixed(1)}\" height=\"410\" fill=\"${bandColor}\" stroke=\"${strokeColor}\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/>`;\n      const lbl = state.maskConn ? `接单根#${idx + 1}(已屏蔽)` : `接单根#${idx + 1}(瞬态冲击)`;\n      html += `<text x=\"${(cx0 + cxW / 2).toFixed(1)}\" y=\"12\" text-anchor=\"middle\" fill=\"${strokeColor}\" font-size=\"10\" font-weight=\"600\">${lbl}</text>`;\n    });\n\n    // Precursor evolution zone & Incident line\n    const px0 = x0 + (ep.precursorIdx / (N - 1)) * xW;\n    const ix0 = x0 + (ep.incidentIdx / (N - 1)) * xW;\n    if (state.showZone) {\n      html += `<rect x=\"${px0.toFixed(1)}\" y=\"16\" width=\"${(ix0 - px0).toFixed(1)}\" height=\"410\" fill=\"rgba(180,72,60,0.06)\"/>`;\n      html += `<line x1=\"${px0.toFixed(1)}\" y1=\"16\" x2=\"${px0.toFixed(1)}\" y2=\"426\" stroke=\"#c27a2c\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>`;\n      html += `<text x=\"${(px0 + 4).toFixed(1)}\" y=\"28\" fill=\"#c27a2c\" font-size=\"10\" font-weight=\"600\">前兆起点 ${(ep.precursorIdx * DT_MIN).toFixed(0)}m</text>`;\n    }\n    // Incident vertical line at 50 min\n    html += `<line x1=\"${ix0.toFixed(1)}\" y1=\"16\" x2=\"${ix0.toFixed(1)}\" y2=\"426\" stroke=\"#b4483c\" stroke-width=\"2\"/>`;\n    html += `<rect x=\"${(ix0 - 38).toFixed(1)}\" y=\"2\" width=\"76\" height=\"15\" rx=\"4\" fill=\"#b4483c\"/>`;\n    html += `<text x=\"${ix0.toFixed(1)}\" y=\"13\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"10\" font-weight=\"600\">事故发生 50m</text>`;\n\n    // Track 1: Hookload (1060..1300 kN) & ROP (0..26 m/h)\n    const pHkld = buildPath(sim.hkld, x0, xW, tracks[0].y0 + 4, tracks[0].yH - 8, 1050, 1290);\n    const pRop  = buildPath(sim.rop,  x0, xW, tracks[0].y0 + 4, tracks[0].yH - 8, 0, 26);\n    html += `<path d=\"${pRop}\" fill=\"none\" stroke=\"#6b5aa6\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\" opacity=\"0.85\"/>`;\n    html += `<path d=\"${pHkld}\" fill=\"none\" stroke=\"#3a6ea5\" stroke-width=\"1.6\"/>`;\n    html += `<rect x=\"${x0 + 6}\" y=\"${tracks[0].y0 + 3}\" width=\"186\" height=\"14\" rx=\"3\" fill=\"rgba(255,255,255,0.86)\"/>`;\n    html += `<text x=\"${x0 + 10}\" y=\"${tracks[0].y0 + 13}\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"600\">实线:大钩载荷(kN) · 虚线:钻速ROP(m/h)</text>`;\n\n    // Track 2: Torque (12..34 kN·m) + baseline\n    const pBTorq = buildPath(sim.bTorq, x0, xW, tracks[1].y0 + 4, tracks[1].yH - 8, 13, 33);\n    const pTorq  = buildPath(sim.torq,  x0, xW, tracks[1].y0 + 4, tracks[1].yH - 8, 13, 33);\n    html += `<path d=\"${pBTorq}\" fill=\"none\" stroke=\"#a3aab0\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>`;\n    html += `<path d=\"${pTorq}\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.75\"/>`;\n    html += `<rect x=\"${x0 + 6}\" y=\"${tracks[1].y0 + 3}\" width=\"168\" height=\"14\" rx=\"3\" fill=\"rgba(255,255,255,0.86)\"/>`;\n    html += `<text x=\"${x0 + 10}\" y=\"${tracks[1].y0 + 13}\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"600\">转盘扭矩 Torque (灰虚线:地层基线)</text>`;\n\n    // Track 3: SPP (14..32 MPa) + baseline\n    const pBSpp = buildPath(sim.bSpp, x0, xW, tracks[2].y0 + 4, tracks[2].yH - 8, 13, 31);\n    const pSpp  = buildPath(sim.spp,  x0, xW, tracks[2].y0 + 4, tracks[2].yH - 8, 13, 31);\n    html += `<path d=\"${pBSpp}\" fill=\"none\" stroke=\"#a3aab0\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>`;\n    html += `<path d=\"${pSpp}\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"1.75\"/>`;\n    html += `<rect x=\"${x0 + 6}\" y=\"${tracks[2].y0 + 3}\" width=\"152\" height=\"14\" rx=\"3\" fill=\"rgba(255,255,255,0.86)\"/>`;\n    html += `<text x=\"${x0 + 10}\" y=\"${tracks[2].y0 + 13}\" fill=\"#12615a\" font-size=\"9.5\" font-weight=\"600\">立管压力 SPP (灰虚线:地层基线)</text>`;\n\n    // Track 4: dQ (-10..+10 L/s) & Pit dV (-3..+3 m³)\n    const pDq = buildPath(sim.dq, x0, xW, tracks[3].y0 + 4, tracks[3].yH - 8, -10, 10);\n    const pDv = buildPath(sim.dv, x0, xW, tracks[3].y0 + 4, tracks[3].yH - 8, -3.2, 3.2);\n    html += `<path d=\"${pDv}\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"1.5\" stroke-dasharray=\"4,2\"/>`;\n    html += `<path d=\"${pDq}\" fill=\"none\" stroke=\"#2f7d5b\" stroke-width=\"1.7\"/>`;\n    html += `<rect x=\"${x0 + 6}\" y=\"${tracks[3].y0 + 3}\" width=\"184\" height=\"14\" rx=\"3\" fill=\"rgba(255,255,255,0.86)\"/>`;\n    html += `<text x=\"${x0 + 10}\" y=\"${tracks[3].y0 + 13}\" fill=\"#2f7d5b\" font-size=\"9.5\" font-weight=\"600\">实线:流量差ΔQ(L/s) · 红虚线:池增量ΔV(m³)</text>`;\n\n    // Track 5: Anomaly Score S(t) (0..8.5)\n    const t5 = tracks[4];\n    const sMax = 8.5;\n    const pSingle = buildPath(sim.singleScore, x0, xW, t5.y0 + 6, t5.yH - 12, 0, sMax);\n    const pActive = buildPath(sim.activeScore, x0, xW, t5.y0 + 6, t5.yH - 12, 0, sMax);\n    const areaD = `${pActive}L${x1},${t5.y0 + t5.yH - 6}L${x0},${t5.y0 + t5.yH - 6}Z`;\n\n    html += `<path d=\"${areaD}\" fill=\"url(#dhw-demo-score-grad)\"/>`;\n    html += `<path d=\"${pSingle}\" fill=\"none\" stroke=\"#737c83\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\" opacity=\"0.8\"/>`;\n    html += `<path d=\"${pActive}\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.2\"/>`;\n\n    // Yellow & Red threshold lines on Track 5\n    const yRed = t5.y0 + 6 + (t5.yH - 12) * (1 - Math.min(sMax, state.thresh) / sMax);\n    const yYel = t5.y0 + 6 + (t5.yH - 12) * (1 - Math.min(sMax, sim.metrics.yellowTh) / sMax);\n    html += `<line x1=\"${x0}\" y1=\"${yYel.toFixed(1)}\" x2=\"${x1}\" y2=\"${yYel.toFixed(1)}\" stroke=\"#c27a2c\" stroke-width=\"1.2\" stroke-dasharray=\"5,3\"/>`;\n    html += `<line x1=\"${x0}\" y1=\"${yRed.toFixed(1)}\" x2=\"${x1}\" y2=\"${yRed.toFixed(1)}\" stroke=\"#b4483c\" stroke-width=\"1.6\" stroke-dasharray=\"6,3\"/>`;\n    html += `<text x=\"${x0 + 6}\" y=\"${(yRed - 4).toFixed(1)}\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"600\">红警阈值 ${state.thresh.toFixed(1)}σ</text>`;\n\n    // Mark false alarms if any\n    sim.metrics.faIndices.forEach(fi => {\n      const fx = x0 + (fi / (N - 1)) * xW;\n      const fy = t5.y0 + 6 + (t5.yH - 12) * (1 - Math.min(sMax, sim.activeScore[fi]) / sMax);\n      html += `<circle cx=\"${fx.toFixed(1)}\" cy=\"${fy.toFixed(1)}\" r=\"4.5\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"1.5\"/>`;\n      html += `<text x=\"${fx.toFixed(1)}\" y=\"${(fy - 7).toFixed(1)}\" text-anchor=\"middle\" fill=\"#c27a2c\" font-size=\"9.5\" font-weight=\"700\">误报!</text>`;\n    });\n\n    // Mark true early warning point & Lead Time ΔT arrow\n    if (sim.metrics.alarmIdx >= 0) {\n      const ax = x0 + (sim.metrics.alarmIdx / (N - 1)) * xW;\n      const ay = yRed;\n      html += `<circle cx=\"${ax.toFixed(1)}\" cy=\"${ay.toFixed(1)}\" r=\"5\" fill=\"#b4483c\" stroke=\"#fff\" stroke-width=\"1.5\"/>`;\n      if (state.showZone && ax < ix0 - 18) {\n        const midX = (ax + ix0) / 2;\n        const arrY = Math.max(t5.y0 + 18, ay - 12);\n        html += `<line x1=\"${ax.toFixed(1)}\" y1=\"${arrY.toFixed(1)}\" x2=\"${ix0.toFixed(1)}\" y2=\"${arrY.toFixed(1)}\" stroke=\"#b4483c\" stroke-width=\"1.8\"/>`;\n        html += `<rect x=\"${(midX - 52).toFixed(1)}\" y=\"${(arrY - 10).toFixed(1)}\" width=\"104\" height=\"16\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\" stroke-width=\"1\"/>`;\n        html += `<text x=\"${midX.toFixed(1)}\" y=\"${(arrY + 2).toFixed(1)}\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"10\" font-weight=\"700\">提前量 ΔT=${sim.metrics.leadMin.toFixed(1)}m</text>`;\n      }\n    }\n\n    // Interactive Time Cursor\n    const curX = x0 + (state.cursor / (N - 1)) * xW;\n    html += `<line x1=\"${curX.toFixed(1)}\" y1=\"14\" x2=\"${curX.toFixed(1)}\" y2=\"428\" stroke=\"#15191c\" stroke-width=\"1.6\"/>`;\n    html += `<polygon points=\"${curX - 6},14 ${curX + 6},14 ${curX},22\" fill=\"#15191c\"/>`;\n\n    svg.innerHTML = html;\n  }\n\n  function computeCursorAttribution(idx) {\n    const sim = state.sim;\n    const rawAbs = [\n      { name: '转盘扭矩 Torque', val: Math.abs(sim.zCh[0][idx]), sign: sim.zCh[0][idx], color: '#c27a2c' },\n      { name: '立管压力 SPP',    val: Math.abs(sim.zCh[1][idx]), sign: sim.zCh[1][idx], color: '#12615a' },\n      { name: '返出流量差 ΔQ',   val: Math.abs(sim.zCh[2][idx]), sign: sim.zCh[2][idx], color: '#2f7d5b' },\n      { name: '泥浆池增量 ΔV',   val: Math.abs(sim.zCh[3][idx]), sign: sim.zCh[3][idx], color: '#b4483c' },\n      { name: '大钩载荷 Hookload', val: Math.abs(sim.zCh[4][idx]), sign: sim.zCh[4][idx], color: '#3a6ea5' },\n      { name: '机械钻速 ROP',    val: Math.abs(sim.zCh[5][idx]), sign: sim.zCh[5][idx], color: '#6b5aa6' }\n    ];\n    let sum = 0.001;\n    rawAbs.forEach(c => { sum += c.val; });\n    rawAbs.forEach(c => { c.pct = Math.round((c.val / sum) * 100); });\n\n    // Pattern matching probabilities for the 3 hazards based on directional signature\n    const zT = sim.zCh[0][idx], zP = sim.zCh[1][idx], zQ = sim.zCh[2][idx], zV = sim.zCh[3][idx], zR = sim.zCh[5][idx];\n    const sStick = Math.max(0.1, (zT > 0 ? zT * 1.4 : 0) + (zP > 0 ? zP * 1.2 : 0) + (zQ < 0 ? -zQ * 0.4 : 0));\n    const sLost  = Math.max(0.1, (zQ < 0 ? -zQ * 1.5 : 0) + (zV < 0 ? -zV * 1.3 : 0) + (zP < 0 ? -zP * 0.8 : 0));\n    const sKick  = Math.max(0.1, (zQ > 0 ? zQ * 1.5 : 0) + (zV > 0 ? zV * 1.3 : 0) + (zR > 0 ? zR * 0.9 : 0));\n    const tot = sStick + sLost + sKick;\n    const probs = [\n      { label: '岩屑床卡钻', p: Math.round((sStick / tot) * 100), col: '#c27a2c' },\n      { label: '裂缝性井漏', p: Math.round((sLost / tot) * 100),  col: '#3a6ea5' },\n      { label: '气侵溢流',   p: Math.max(0, 100 - Math.round((sStick / tot) * 100) - Math.round((sLost / tot) * 100)), col: '#b4483c' }\n    ];\n    return { channels: rawAbs, probs };\n  }\n\n  function renderAuxAttribution() {\n    const svg = document.getElementById('aux-attr-svg');\n    const idx = state.cursor;\n    const { channels, probs } = computeCursorAttribution(idx);\n    document.getElementById('attr-time-tag').textContent = `@ t = ${(idx * DT_MIN).toFixed(1)} min`;\n\n    let html = `<rect x=\"0\" y=\"0\" width=\"420\" height=\"250\" fill=\"#ffffff\"/>`;\n    html += `<text x=\"14\" y=\"20\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"600\">六通道重构残差贡献占比 (Root-Cause Attribution)</text>`;\n\n    channels.forEach((ch, i) => {\n      const y = 32 + i * 23;\n      const bw = Math.max(3, (ch.pct / 55) * 175);\n      const dir = ch.sign >= 0.15 ? '↑' : ch.sign <= -0.15 ? '↓' : '·';\n      html += `<text x=\"14\" y=\"${y + 11}\" fill=\"#424a50\" font-size=\"11\">${ch.name}</text>`;\n      html += `<rect x=\"128\" y=\"${y + 1}\" width=\"185\" height=\"12\" rx=\"3\" fill=\"#f0ede5\"/>`;\n      html += `<rect x=\"128\" y=\"${y + 1}\" width=\"${Math.min(185, bw).toFixed(1)}\" height=\"12\" rx=\"3\" fill=\"${ch.color}\"/>`;\n      html += `<text x=\"320\" y=\"${y + 11}\" fill=\"#15191c\" font-size=\"11\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"600\">${ch.pct}% (${dir}${Math.abs(ch.sign).toFixed(1)}σ)</text>`;\n    });\n\n    // Bottom section: 3-class hazard pattern probability bars\n    html += `<line x1=\"14\" y1=\"176\" x2=\"406\" y2=\"176\" stroke=\"#e7e3da\"/>`;\n    html += `<text x=\"14\" y=\"194\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"600\">多参数耦合签名匹配概率 (物理机理分类器)</text>`;\n\n    probs.forEach((pr, i) => {\n      const x = 14 + i * 132;\n      html += `<rect x=\"${x}\" y=\"204\" width=\"124\" height=\"36\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>`;\n      html += `<text x=\"${x + 8}\" y=\"219\" fill=\"#424a50\" font-size=\"11\" font-weight=\"600\">${pr.label}</text>`;\n      html += `<text x=\"${x + 116}\" y=\"219\" text-anchor=\"end\" fill=\"${pr.col}\" font-size=\"12\" font-family=\"ui-monospace,Consolas,monospace\" font-weight=\"700\">${pr.p}%</text>`;\n      html += `<rect x=\"${x + 8}\" y=\"226\" width=\"108\" height=\"6\" rx=\"3\" fill=\"#eae6dc\"/>`;\n      html += `<rect x=\"${x + 8}\" y=\"226\" width=\"${(1.08 * pr.p).toFixed(1)}\" height=\"6\" rx=\"3\" fill=\"${pr.col}\"/>`;\n    });\n\n    svg.innerHTML = html;\n  }\n\n  function renderAuxWellAndTradeoff() {\n    const svg = document.getElementById('aux-well-svg');\n    const sim = state.sim;\n    const idx = state.cursor;\n    const ep = sim.epCfg;\n    const curMin = idx * DT_MIN;\n    const depth = (ep.baseDepth + curMin * 0.22).toFixed(1);\n    document.getElementById('well-depth-tag').textContent = `钻头井深 ${depth} m`;\n\n    const severity = Math.min(1, Math.max(0, (idx - ep.precursorIdx) / (ep.incidentIdx - ep.precursorIdx)));\n\n    let html = `<rect x=\"0\" y=\"0\" width=\"420\" height=\"250\" fill=\"#ffffff\"/>`;\n    // Left half (x: 10..168): Dynamic Wellbore Annulus Schematic\n    html += `<text x=\"14\" y=\"20\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"600\">井筒环空实时状态剖面</text>`;\n    html += `<rect x=\"16\" y=\"28\" width=\"144\" height=\"210\" rx=\"6\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>`;\n\n    // Formation strata layers\n    html += `<rect x=\"22\" y=\"36\" width=\"132\" height=\"55\" fill=\"#e4d6b8\" opacity=\"0.45\"/>`;\n    html += `<rect x=\"22\" y=\"91\" width=\"132\" height=\"65\" fill=\"#d9c7a3\" opacity=\"0.5\"/>`;\n    html += `<rect x=\"22\" y=\"156\" width=\"132\" height=\"74\" fill=\"#c9b28a\" opacity=\"0.55\"/>`;\n\n    // Borehole wall & Annulus\n    html += `<rect x=\"56\" y=\"36\" width=\"64\" height=\"194\" fill=\"#e3efec\" stroke=\"#737c83\" stroke-width=\"1.2\"/>`;\n    // Casing shoe at top\n    html += `<path d=\"M56,36 L56,82 L49,88 M120,36 L120,82 L127,88\" fill=\"none\" stroke=\"#15191c\" stroke-width=\"2\"/>`;\n    // Drillpipe & Bit\n    html += `<rect x=\"81\" y=\"36\" width=\"14\" height=\"178\" fill=\"#424a50\"/>`;\n    html += `<rect x=\"75\" y=\"214\" width=\"26\" height=\"14\" rx=\"2\" fill=\"#15191c\"/>`;\n\n    // Hazard-specific visual in annulus\n    if (state.ep === 'sticking') {\n      const packR = (2 + severity * 14).toFixed(1);\n      html += `<ellipse cx=\"68\" cy=\"150\" rx=\"${packR}\" ry=\"28\" fill=\"#c27a2c\" opacity=\"${(0.25 + severity * 0.65).toFixed(2)}\"/>`;\n      html += `<ellipse cx=\"108\" cy=\"150\" rx=\"${packR}\" ry=\"28\" fill=\"#c27a2c\" opacity=\"${(0.25 + severity * 0.65).toFixed(2)}\"/>`;\n      html += `<text x=\"88\" y=\"120\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">${severity > 0.15 ? '岩屑床堆积抱死' : '环空携岩正常'}</text>`;\n    } else if (state.ep === 'lost') {\n      const leakLen = (4 + severity * 30).toFixed(1);\n      html += `<path d=\"M120,162 L${(120 + parseFloat(leakLen)).toFixed(1)},152 M120,174 L${(120 + parseFloat(leakLen)).toFixed(1)},184 M56,168 L${(56 - parseFloat(leakLen)).toFixed(1)},160\" stroke=\"#3a6ea5\" stroke-width=\"${(1.2 + severity * 2.2).toFixed(1)}\" stroke-linecap=\"round\"/>`;\n      html += `<text x=\"88\" y=\"120\" text-anchor=\"middle\" fill=\"#3a6ea5\" font-size=\"9.5\" font-weight=\"700\">${severity > 0.15 ? '诱导裂缝漏失↑' : '井壁封堵完整'}</text>`;\n    } else {\n      const nBub = Math.round(severity * 10);\n      for (let b = 0; b < nBub; b++) {\n        const by = 205 - b * 14 - ((idx * 3) % 10);\n        const bx = b % 2 === 0 ? 68 : 108;\n        html += `<circle cx=\"${bx}\" cy=\"${by}\" r=\"${(2.2 + (b % 3) * 1.1).toFixed(1)}\" fill=\"#b4483c\" opacity=\"0.75\"/>`;\n      }\n      html += `<text x=\"88\" y=\"120\" text-anchor=\"middle\" fill=\"#b4483c\" font-size=\"9.5\" font-weight=\"700\">${severity > 0.15 ? '高压气侵气泡上窜' : '液柱压力平衡'}</text>`;\n    }\n\n    // Right half (x: 176..408): Threshold Sensitivity Tradeoff Curve (ΔT vs False Alarms)\n    html += `<text x=\"180\" y=\"20\" fill=\"#15191c\" font-size=\"11.5\" font-weight=\"600\">阈值灵敏度权衡 (提前量 ΔT vs 误报)</text>`;\n    const rx0 = 204, ry0 = 36, rw = 194, rh = 172;\n    html += `<rect x=\"${rx0}\" y=\"${ry0}\" width=\"${rw}\" height=\"${rh}\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>`;\n\n    // Compute tradeoff curve for thresholds 1.8 .. 5.5\n    let pathLead = '';\n    let pathFa = '';\n    const thMin = 1.8, thMax = 5.5;\n    for (let k = 0; k <= 18; k++) {\n      const thVal = thMin + (k / 18) * (thMax - thMin);\n      const m = evaluateAlarmMetrics(ep, sim.activeScore, thVal);\n      const px = rx0 + (k / 18) * rw;\n      const pyLead = ry0 + rh - (Math.min(24, m.leadMin) / 24) * (rh - 16) - 6;\n      const pyFa   = ry0 + rh - (Math.min(8, m.falseAlarms) / 8) * (rh - 16) - 6;\n      pathLead += (k === 0 ? 'M' : 'L') + px.toFixed(1) + ',' + pyLead.toFixed(1);\n      pathFa   += (k === 0 ? 'M' : 'L') + px.toFixed(1) + ',' + pyFa.toFixed(1);\n    }\n    html += `<path d=\"${pathFa}\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.6\" stroke-dasharray=\"4,2\"/>`;\n    html += `<path d=\"${pathLead}\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2\"/>`;\n\n    // Current threshold vertical marker\n    const curThX = rx0 + ((state.thresh - thMin) / (thMax - thMin)) * rw;\n    const curLeadY = ry0 + rh - (Math.min(24, sim.metrics.leadMin) / 24) * (rh - 16) - 6;\n    html += `<line x1=\"${curThX.toFixed(1)}\" y1=\"${ry0}\" x2=\"${curThX.toFixed(1)}\" y2=\"${ry0 + rh}\" stroke=\"#b4483c\" stroke-width=\"1.3\" stroke-dasharray=\"3,2\"/>`;\n    html += `<circle cx=\"${curThX.toFixed(1)}\" cy=\"${curLeadY.toFixed(1)}\" r=\"4.5\" fill=\"#12615a\" stroke=\"#fff\" stroke-width=\"1.5\"/>`;\n\n    html += `<text x=\"${rx0 + 6}\" y=\"${ry0 + 14}\" fill=\"#12615a\" font-size=\"10\" font-weight=\"600\">— 提前时间 ΔT (0–24m)</text>`;\n    html += `<text x=\"${rx0 + 6}\" y=\"${ry0 + 28}\" fill=\"#c27a2c\" font-size=\"10\" font-weight=\"600\">-- 误报次数 (0–8次)</text>`;\n    html += `<text x=\"${rx0 + rw / 2}\" y=\"226\" text-anchor=\"middle\" fill=\"#737c83\" font-size=\"10.5\">报警阈值门限 (1.8σ → 5.5σ · 当前 ${state.thresh.toFixed(1)}σ)</text>`;\n\n    svg.innerHTML = html;\n  }\n\n  function updateKpisAndInsight() {\n    const sim = state.sim;\n    const ep = sim.epCfg;\n    const m = sim.metrics;\n    const idx = state.cursor;\n    const curMin = (idx * DT_MIN).toFixed(1);\n\n    // Topbar pills\n    const rigPill = document.getElementById('pill-rig');\n    const rigTxt  = document.getElementById('pill-rig-txt');\n    if (sim.connFlag[idx]) {\n      rigPill.className = 'pill warn';\n      rigTxt.textContent = `当前游标 (${curMin}m)：接单根瞬态工况 ${state.maskConn ? '· 已自动屏蔽' : '· 未屏蔽!'}`;\n    } else if (idx >= ep.incidentIdx) {\n      rigPill.className = 'pill bad';\n      rigTxt.textContent = `当前游标 (${curMin}m)：井下复杂事故已发生 (${ep.trueLabel})`;\n    } else if (idx >= ep.precursorIdx) {\n      rigPill.className = 'pill warn';\n      rigTxt.textContent = `当前游标 (${curMin}m)：前兆潜伏演化段 (${ep.trueLabel})`;\n    } else {\n      rigPill.className = 'pill acc';\n      rigTxt.textContent = `当前游标 (${curMin}m)：正常旋转钻进`;\n    }\n\n    const warnPill = document.getElementById('pill-warn');\n    const warnTxt  = document.getElementById('pill-warn-txt');\n    if (m.leadMin >= 10 && m.falseAlarms === 0) {\n      warnPill.className = 'pill ok';\n      warnTxt.textContent = `零误报 · 提前 ${m.leadMin.toFixed(1)} min 触发红警`;\n    } else if (m.leadMin > 0) {\n      warnPill.className = 'pill warn';\n      warnTxt.textContent = `提前 ${m.leadMin.toFixed(1)} min 预警 · 误报 ${m.falseAlarms} 次`;\n    } else {\n      warnPill.className = 'pill bad';\n      warnTxt.textContent = `漏报警告：阈值过高未在事故前触发`;\n    }\n\n    // KPI 1: Lead Time\n    const kLead = document.getElementById('kpi-lead');\n    document.getElementById('kpi-lead-v').innerHTML = m.leadMin > 0 ? `${m.leadMin.toFixed(1)}<small>min</small>` : `0.0<small>min(漏报)</small>`;\n    document.getElementById('kpi-lead-d').textContent = m.alarmIdx >= 0\n      ? `红警触发 t=${(m.alarmIdx * DT_MIN).toFixed(1)} min（事故 50.0 min）`\n      : `直至 50.0 min 事故发生仍未越过阈值`;\n    kLead.className = 'kpi ' + (m.leadMin >= 12 ? 'ok' : m.leadMin >= 5 ? 'warn' : 'bad');\n\n    // KPI 2: False Alarms\n    const kFar = document.getElementById('kpi-far');\n    document.getElementById('kpi-far-v').innerHTML = `${m.falseAlarms}<small>次</small>`;\n    document.getElementById('kpi-far-d').textContent = m.falseAlarms === 0\n      ? (state.maskConn ? '接单根瞬态已被状态机自动屏蔽' : '当前高阈值下无前序误报')\n      : (!state.maskConn ? '12/24 min 接单根停泵/卸扣引发假警报!' : '背景噪声或低阈值引发瞬态误报');\n    kFar.className = 'kpi ' + (m.falseAlarms === 0 ? 'ok' : m.falseAlarms <= 1 ? 'warn' : 'bad');\n\n    // KPI 3 & 4: Type & Action\n    const { probs } = computeCursorAttribution(Math.max(idx, ep.precursorIdx + 60));\n    const topProb = probs.slice().sort((a, b) => b.p - a.p)[0];\n    document.getElementById('kpi-type-v').textContent = `${ep.trueLabel} · ${topProb.p}%`;\n    document.getElementById('kpi-act-v').textContent = ep.advice;\n    document.getElementById('kpi-act-d').textContent = ep.adviceSub;\n\n    // Dynamic Insight\n    const box = document.getElementById('insight-box');\n    const tag = document.getElementById('insight-tag');\n    const txt = document.getElementById('insight-txt');\n\n    if (!state.maskConn) {\n      box.className = 'insight bad';\n      tag.textContent = '工况误报剖析';\n      txt.innerHTML = `当前<b>未启用接单根工况自动屏蔽</b>：在 <b>t = 12 min 与 24 min</b> 正常接单根期间，司钻座卡瓦上提钻具、停泵卸扣导致大钩载荷骤增、立压骤降、扭矩脉冲，触发了 <b>${m.falseAlarms} 次「狼来了」假警报</b>！请勾选左侧「启用接单根工况自动屏蔽」，利用大钩高度与泵冲状态机自动切除瞬态窗口。`;\n    } else if (state.mode === 'single') {\n      box.className = 'insight warn';\n      tag.textContent = '单通道基线局限';\n      txt.innerHTML = `当前采用<b>单通道固定阈值</b>：仅靠单一通道幅值超限判定，在 <b>${ep.name}</b> 早期（28–38 min）各参数处于温和爬升阶段，单通道信噪比低，提前预警时间仅 <b>${m.leadMin.toFixed(1)} min</b>（误报 ${m.falseAlarms} 次）。切换至<b>「多变量残差 + CUSUM 滤波」</b>可捕获多通道协同偏离并大幅延长黄金处置时间窗。`;\n    } else {\n      box.className = 'insight';\n      tag.textContent = 'AI 协同预警诊断';\n      txt.innerHTML = `当前工况为<b>${ep.name}</b>，采用<b>多变量马氏残差 + CUSUM 累积滤波（步长 ${state.cusumWin} 步，阈值 ${state.thresh.toFixed(1)}σ）</b>：状态机成功屏蔽了 12/24 min 两次接单根冲击（<b>0 误报</b>），并在 <b>t = ${(m.alarmIdx >= 0 ? (m.alarmIdx * DT_MIN).toFixed(1) : '--')} min</b> 捕获多通道耦合前兆，比 50.0 min 事故发生时刻<b>提前 ΔT = ${m.leadMin.toFixed(1)} 分钟</b>发出红警，推荐司钻立即执行<b>「${ep.advice}」</b>。`;\n    }\n  }\n\n  function renderAll() {\n    simulateEpisode();\n    renderStripChart();\n    renderAuxAttribution();\n    renderAuxWellAndTradeoff();\n    updateKpisAndInsight();\n  }\n\n  // Bind UI controls\n  function bindEvents() {\n    // Stepper\n    document.querySelectorAll('#stepper button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const s = parseInt(btn.dataset.step, 10);\n        state.step = s;\n        document.querySelectorAll('#stepper button').forEach(b => {\n          const bs = parseInt(b.dataset.step, 10);\n          b.classList.toggle('on', bs === s);\n          b.classList.toggle('done', bs < s);\n        });\n        if (s === 1) { state.mode = 'single'; state.maskConn = true; }\n        else if (s === 2) { state.mode = 'single'; }\n        else if (s === 3) { state.mode = 'mahal'; }\n        else { state.mode = 'cusum'; }\n        syncControlsFromState();\n        renderAll();\n      });\n    });\n\n    // Episode selector\n    document.querySelectorAll('#ep-list .ep-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.ep = btn.dataset.ep;\n        document.querySelectorAll('#ep-list .ep-btn').forEach(b => b.classList.toggle('on', b === btn));\n        renderAll();\n      });\n    });\n\n    // Mode selector\n    document.querySelectorAll('#mode-seg button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.mode = btn.dataset.mode;\n        document.querySelectorAll('#mode-seg button').forEach(b => b.classList.toggle('on', b === btn));\n        renderAll();\n      });\n    });\n\n    // Sliders\n    const slThresh = document.getElementById('sl-thresh');\n    const slCusum  = document.getElementById('sl-cusum');\n    const slNoise  = document.getElementById('sl-noise');\n    const slCursor = document.getElementById('sl-cursor');\n\n    slThresh.addEventListener('input', () => {\n      state.thresh = parseFloat(slThresh.value);\n      document.getElementById('val-thresh').textContent = state.thresh.toFixed(1) + ' σ';\n      updateRangeProgress(slThresh);\n      renderAll();\n    });\n\n    slCusum.addEventListener('input', () => {\n      state.cusumWin = parseInt(slCusum.value, 10);\n      document.getElementById('val-cusum').textContent = `${state.cusumWin} 步 (${state.cusumWin * 10}s)`;\n      updateRangeProgress(slCusum);\n      renderAll();\n    });\n\n    slNoise.addEventListener('input', () => {\n      state.noise = parseFloat(slNoise.value);\n      document.getElementById('val-noise').textContent = state.noise.toFixed(2) + '×';\n      updateRangeProgress(slNoise);\n      renderAll();\n    });\n\n    slCursor.addEventListener('input', () => {\n      state.cursor = parseInt(slCursor.value, 10);\n      document.getElementById('txt-cursor').textContent = `t = ${(state.cursor * DT_MIN).toFixed(1)} min (步 #${state.cursor})`;\n      updateRangeProgress(slCursor);\n      renderStripChart();\n      renderAuxAttribution();\n      renderAuxWellAndTradeoff();\n      updateKpisAndInsight();\n    });\n\n    // Checkboxes\n    const chkMask = document.getElementById('chk-mask');\n    const chkZone = document.getElementById('chk-zone');\n    chkMask.addEventListener('change', () => {\n      state.maskConn = chkMask.checked;\n      renderAll();\n    });\n    chkZone.addEventListener('change', () => {\n      state.showZone = chkZone.checked;\n      renderAll();\n    });\n\n    // Interactive scrubbing on SVG strip chart + hover tooltip\n    const stripSvg = document.getElementById('strip-svg');\n    const tip = document.getElementById('strip-tip');\n    let dragging = false;\n\n    function updateCursorFromEvent(e) {\n      const rect = stripSvg.getBoundingClientRect();\n      const relX = ((e.clientX - rect.left) / rect.width) * 840;\n      const idx = Math.round(((relX - 96) / 724) * (N - 1));\n      const clamped = Math.max(0, Math.min(N - 1, idx));\n      state.cursor = clamped;\n      slCursor.value = String(clamped);\n      document.getElementById('txt-cursor').textContent = `t = ${(clamped * DT_MIN).toFixed(1)} min (步 #${clamped})`;\n      updateRangeProgress(slCursor);\n      renderStripChart();\n      renderAuxAttribution();\n      renderAuxWellAndTradeoff();\n      updateKpisAndInsight();\n\n      // Show tooltip\n      const sim = state.sim;\n      tip.innerHTML = `<b>t = ${(clamped * DT_MIN).toFixed(1)} min</b> · 指数 S=${sim.activeScore[clamped].toFixed(2)}σ<br>` +\n        `扭矩 ${sim.torq[clamped].toFixed(1)} kN·m | 立压 ${sim.spp[clamped].toFixed(1)} MPa | ΔQ ${sim.dq[clamped].toFixed(1)} L/s`;\n      tip.style.left = Math.max(70, Math.min(rect.width - 70, e.clientX - rect.left)) + 'px';\n      tip.style.top = Math.max(45, e.clientY - rect.top) + 'px';\n      tip.classList.add('on');\n    }\n\n    stripSvg.addEventListener('mousedown', (e) => { dragging = true; updateCursorFromEvent(e); });\n    window.addEventListener('mousemove', (e) => { if (dragging) updateCursorFromEvent(e); });\n    window.addEventListener('mouseup', () => { dragging = false; });\n    stripSvg.addEventListener('mousemove', (e) => { if (!dragging) updateCursorFromEvent(e); });\n    stripSvg.addEventListener('mouseleave', () => { tip.classList.remove('on'); });\n\n    // Play & Reset buttons\n    const btnPlay = document.getElementById('btn-play');\n    btnPlay.addEventListener('click', () => {\n      if (state.playing) {\n        stopPlay();\n      } else {\n        state.playing = true;\n        btnPlay.textContent = '⏸ 暂停回放';\n        if (state.cursor >= N - 5) state.cursor = 0;\n        state.playTimer = setInterval(() => {\n          state.cursor = (state.cursor + 2) % N;\n          slCursor.value = String(state.cursor);\n          document.getElementById('txt-cursor').textContent = `t = ${(state.cursor * DT_MIN).toFixed(1)} min (步 #${state.cursor})`;\n          updateRangeProgress(slCursor);\n          renderStripChart();\n          renderAuxAttribution();\n          renderAuxWellAndTradeoff();\n          updateKpisAndInsight();\n          if (state.cursor >= N - 3) stopPlay();\n        }, 65);\n      }\n    });\n\n    document.getElementById('btn-reset').addEventListener('click', () => {\n      stopPlay();\n      state.ep = 'sticking';\n      state.mode = 'cusum';\n      state.step = 5;\n      state.thresh = 3.2;\n      state.cusumWin = 8;\n      state.noise = 0.6;\n      state.maskConn = true;\n      state.showZone = true;\n      state.cursor = 234;\n      syncControlsFromState();\n      renderAll();\n    });\n  }\n\n  function stopPlay() {\n    state.playing = false;\n    if (state.playTimer) clearInterval(state.playTimer);\n    state.playTimer = null;\n    document.getElementById('btn-play').textContent = '▶ 巡检回放';\n  }\n\n  function syncControlsFromState() {\n    document.querySelectorAll('#ep-list .ep-btn').forEach(b => b.classList.toggle('on', b.dataset.ep === state.ep));\n    document.querySelectorAll('#mode-seg button').forEach(b => b.classList.toggle('on', b.dataset.mode === state.mode));\n    const slThresh = document.getElementById('sl-thresh');\n    const slCusum  = document.getElementById('sl-cusum');\n    const slNoise  = document.getElementById('sl-noise');\n    const slCursor = document.getElementById('sl-cursor');\n    slThresh.value = String(state.thresh);\n    slCusum.value  = String(state.cusumWin);\n    slNoise.value  = String(state.noise);\n    slCursor.value = String(state.cursor);\n    document.getElementById('val-thresh').textContent = state.thresh.toFixed(1) + ' σ';\n    document.getElementById('val-cusum').textContent = `${state.cusumWin} 步 (${state.cusumWin * 10}s)`;\n    document.getElementById('val-noise').textContent = state.noise.toFixed(2) + '×';\n    document.getElementById('txt-cursor').textContent = `t = ${(state.cursor * DT_MIN).toFixed(1)} min (步 #${state.cursor})`;\n    document.getElementById('chk-mask').checked = state.maskConn;\n    document.getElementById('chk-zone').checked = state.showZone;\n    [slThresh, slCusum, slNoise, slCursor].forEach(updateRangeProgress);\n  }\n\n  syncControlsFromState();\n  bindEvents();\n  renderAll();\n})();\n","enc":"text","size":44298}]};